export default [{"id":410,"question":"من المعروف أنَّ نكاح الكتابية جائزٌ، ولكن بعض العلماء يمنع ذلك في الوقت الحاضر؛ لكونهم قد أصبحوا مشركين، ويعبدون المسيح، ويدعونه من دون الله، وبعضهم لا يلتزم بالديانة المُحرّفة، فما الحكم في ذلك؟","title":"حكم الزواج من الكتابية","answer":"الجواب: الأصل بقاء ما كان على ما كان، إن كانت نصرانيةً تدين بالنصرانية، وتنتسب إلى النصرانية، وهي مُحْصَنة معروفة بالإحصان لا بالبغاء، معروفة بالإحصان؛ لأنَّ الله إنما ذكر المحصنات، فيجوز ذلك، لكن ترك ذلك أفضل.\nولهذا كره ذلك عمر وجماعةٌ؛ خوفًا على المسلمين أن تجرّهم إلى النصرانية، أو تجرّ أولادهم، وإذا كان هذا في عهد عمر فكيف بعهدنا؟!\nفالخطر عظيم، والذي ينبغي ألا يتزوجها أبدًا؛ لأنها ولو كانت مباحةً لكن شرَّها عظيمٌ؛ لخبثهم، وضعف إيمان المسلم في الغالب، وما في هذا من الخطر عليه وعلى ذريته، فالأحوط له والأوْلى به ألا يتزوجها أصلًا؛ لما في ذلك من الخطر العظيم.","link":"https://binbaz.org.sa/fatwas/4826/حكم-الزواج-من-الكتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0468.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":928,"question":"يقول: خادمة من الفلبين أسلمتْ، ولها أولاد، ولكن زوجها ما زال نصرانيًّا، فقيل لها: أنه لا بد ألا ترجع إلى زوجها، فقالت: لا أستطيع، فما الحكم في هذا؟","title":"ما حكم مَن أسلمت وزوجها ما زال نصرانيَّا؟","answer":"الجواب: إذا أسلمت وزوجها باقٍ على النصرانية ليس لها الرجوعُ إليه، بل تمتنع منه حتى يُسلم، فإن أسلم وهي في العدَّة فهي زوجته، وإن خرجت من العدَّة فهي بانت منه حينئذٍ.\nوقال بعضُ أهل العلم: إنها لا تبين منه إذا أسلم بعد ذلك وهي لم تتزوج، ولم تفسخ منه، ولم يُطلِّق. فعلى كل حال بخروجها من العدة انتهت، لها أن تتزوج، وللحاكم الشرعي أن يُزوّجها؛ لأنَّ نكاحها انتهى بخروجها من العدَّة، لكن لو انتظرت لعله يُسلم هذا الصواب، أنه يرجع إليها ولو بعد العدَّة؛ لأن الرسول ﷺ أعاد ابنته زينب على أبي العاص ابن الربيع لما أسلم عام الفتح، وقد مضى عليها سنوات؛ لأنها تنتظره، فهذا هو الصواب. وإن تزوجت بعد العدَّة ولم تنتظره فلا بأس عليها، وعليها أن تتَّقي الله جلَّ وعلا، وأن تعلم أنَّ هذا هو الحكم الشرعي، وعلى إخوانها المسلمين أن يُعلِّموها ويُوجِّهوها، حتى لا ترجع إليه، وحتى لا ترتدَّ عن دينها، نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/20956/ما-حكم-من-اسلمت-وزوجها-ما-زال-نصرانيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0752أمرأة من النصارى أسلمت ولها أولاد لكن زوجها مازال نصرانياً فما الحكم؟ ابن باز فتاوى المحاضرات.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":1006,"question":"رجلٌ كان مسيحيًّا فأسلم والحمد لله، وزوجته لا تزال باقيةً على دينها السابق، فما حكم بقائها على ذمَّته وهي لم تُسلم؟ جزاكم الله خيرًا.","title":"ما حكم بقاء زوجة النصراني معه بعد إسلامه؟","answer":"الجواب: ما دامت مسيحية لا بأس؛ لأن المسلم لا بأس أن يبقى مع الكتابية، وينكحها أيضًا من جديدٍ، يتزوجها إذا كانت محصنةً، فإذا كانت زوجته محصنةً وأحبَّ أن يبقى معها فلا بأس، لعلَّ الله يهديها للإسلام بأسبابه، وإن أحبَّ أن يُطلقها فلا بأس. أما إن كانت غير نصرانية بل وثنية؛ فإنه ينفسخ النكاحُ، إذا انتهت العدَّةُ ينفسخ النكاح بإسلامه، فإن أسلمت فهي زوجته، وإلا انفسخ النكاحُ، فلها أن تنكح بعد ذلك بعد خروجها بعد العدَّة. أما إذا كانت كتابيةً -يهودية أو نصرانية- تبقى معه؛ لأن المسلم يجوز له نكاح الكتابية المحصنة. وعدم نكاحه لها أسلم له وأبعد عن الشرِّ، فإذا فارقها احتياطًا خوفًا أن تجرَّه إلى دينها فهذا طيبٌ. وإن كان يطمع في إسلامها ويرجو إسلامها لا يعجل، لعلَّ الله يهديها بأسبابه، فإذا انتهت العدَّةُ -حاضت ثلاث حيضٍ- ولم تُسلم؛ انتهت من النكاح، وصار لها أن تنكح مَن شاءت.","link":"https://binbaz.org.sa/fatwas/21047/ما-حكم-بقاء-زوجة-النصراني-معه-بعد-اسلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0843رجل كان نصرانياً فاسلم وزجته ما زالت باقيةعلى دينها فما حكم بقاؤها على ذمته وهي لم تسلم؟ ابن باز.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":2417,"question":"سمعتك تقول غير مرة أن الذي يتعمد تأخير صلاة الفجر يكون كافرًا، فهل بناء على هذا إذا عقد عقد زواج وهو ما يصلي الفجر صحيح؟","title":"هل يصح زواج وعَقْدُ مَن لا يصلي الفجر؟","answer":"الجواب:\nهذا على خلاف، الجمهور على أنه إذا كان ما جحد وجوبها لا يكفر وإنما يكفر كفرًا أصغر، والصحيح أنه كفر أكبر إذا تعمد ترك الصلاة حتى خرج وقتها عمدًا بغير شُبهة، والكافر لا يعقد للمسلمة، إذا كان وليها لا يصلي فيلتمس وليًّا آخر، الذي لا يصلي لا يتولى عقدها، الذي ما يصلي أبوها ما يصلي يعقد لها أخوها أو ابن أو عم؛ الأقرب فالأقرب.\nس: هو سوف يتزوج الآن؟\nالشيخ: وهي ما تصلي وهو يصلي؟\nس: هو الذي ما يصلي، يترك صلاة الفجر عمدا.\nالشيخ: لا، لا يُزَوَّج ينبغي لهم ألا يزوجوه، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/22545/هل-يصح-زواج-وعقد-من-لا-يصلي-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صحة عقد من لا يصلي الفجر.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":7580,"question":"هذه الرسالة وردت من قطر من الدوحة يقول مقدمها محمد عبد الله الدوسري: السلام عليكم ورحمة الله وبركاته، وأرجو حل مشكلتي فأنا حائر في أمري هذا، والسؤال كما يلي: عندي ابن أخت عاهدته وحلفت له أنني أزوجه ابنتي إذا كان مواظباً على الصلاة، وإذا لم يصل فليس له عندي أي شيء، أعني: لم أزوجه، وثم جاء يخطب، قلت له: يا ولدي! كل أعمالك طيبة إلا ترك الصلاة، وأنا ليس أوافق عليك، فظل في عناده ثم راح وتزوج ولا زال مصراً على عدم المبالاة بالصلاة، فهل علي حرج من قبل العهد واليمين، وهل علي كفارة في ذلك؟ أفيدونا مأجورين أثابكم الله تعالى؟","title":"حكم تزويج تارك الصلاة","answer":"الجواب: أولاً تزويج الشخص الذي لا يصلي لا يجوز، لا يجوز أن يزوج شخص لا يصلي بالمسلمة؛ لأن ترك الصلاة كفر، كما قال النبي عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، فالذي لا يصلي كافر ولا يجوز أن يزوج بمسلمة، كما قال الله جل وعلا في الكفار: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]، وقال سبحانه وتعالى: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221]، ثم قال بعده: )وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا( [البقرة:221]. \nفالذي عليه المحققون من أهل العلم: أن تارك الصلاة كسلاً وتهاوناً كافر بنص الرسول عليه الصلاة والسلام، أما من تركها جاحداً لوجوبها هذا كافر عند الجميع، هذا كافر عند جميع أهل العلم، كل من جحد ما أوجب الله مما هو معلوم من الدين بالضرورة كالصلاة، والزكاة، والصيام رمضان، والحج.. وما أشبه ذلك، فإنه يكون كافراً كفراً أكبر ناقلاً من الملة عند جميع أهل العلم، لكن الصلاة بوجه أخص إذا تركها تكاسلاً مع إيمانه بوجوبها فإنه يكفر بذلك كفراً أكبر على الراجح من أقوال العلماء، وبهذا يعلم أن هذا الرجل الذي لا يصلي لا يجوز تزويجه، وعليك كفارة، أن تكفر عن يمينك بإطعام عشرة مساكين؛ لأنك فعلت خلاف يمينك ونقضتها، فعليك الكفارة بإطعام عشرة مساكين لكل مسكين نصف صاع من قوت البلد أو كسوتهم على قميص قميص، أو إزار ورداء، هذه كفارة اليمين. \nوعليك أيضاً أن تسعى في تخليص ابنتك منه، إما أن يطلقها بدون محاكمة، وإما أن تحاكمه إلى المحكمة الشرعية وهي تنظر في أمره وتعمل ما يقتضي الشرع في فسخ النكاح إذا ثبت أنه لا يصلي، ولا حول ولا قوة إلا بالله. \nونوصي جميع أولياء النساء أن يتقوا الله في النساء، وأن لا يزوجوهن ممن يعرف بترك الصلاة، فإن ترك الصلاة كفر أكبر؛ لأن الصلاة عمود الإسلام، فمن ضيعها فقد ضيع دينه، ومن حفظها فقد حفظ دينه، فالواجب على أولياء النساء وعلى النساء أنفسهن، الواجب على الجميع الحذر من التزوج ممن يترك الصلاة، فإن تارك الصلاة لا يؤمن وخيره قليل وشره كثير وليس مع الكفر ذنب من ترك الصلاة فقد كفر نسأل الله العافية. \nفنسأل الله أن يهدي جميع المسلمين، نسأل الله أن يهدينا جميعاً وجميع المسلمين، شباباً وشيباً، رجالاً ونساء، وأن يمن على الجميع بالتوفيق والثبات على الحق، والعافية من نزغات الشيطان. نعم. \nالمقدم: سماحة الشيخ! هو لم يزوجه ابنته؛ لأنه يقول: ظل في عناده ثم راح وتزوج ولا زال مصراً على عدم المبالاة بالصلاة، فهل علي حرج؛ لأنه قال في أول رسالته: ابن أخت عاهدته وحلفت له أنني أزوجه ابنتي إذا كان مواظباً على الصلاة، فهو يسأل: هل عليه في حلفه إذ لم يزوجه ابنته؟ \nالشيخ: لا، مادام ما زوجه فقد أحسن، زوجه من غير البنت فهذا ... \nالمقدم: نعم، زوجه من غير ابنته.\nالشيخ: فقد أحسن ولا يزوجه؛ لأن هذا لا يزوج، وليس عليه في يمينه شيء، قد أحسن وأفاد وأجاد، وهذا هو الواجب عليه أن لا يزوج شخصاً يضيع عمود الإسلام، نسأل الله العافية. نعم. \nالمقدم: لكن هل يلزمه كفارة في..؟\nالشيخ: ما دام ما زوجه ما عليه كفارة؛ هذاك لو زوجه.\nالمقدم: لأنه يقول: عاهدته وحلفت له أنني أزوجه ابنتي إذا كان مواظباً؟\nالشيخ: هذا ما واظب ولا زوجه.","link":"https://binbaz.org.sa/fatwas/4586/حكم-تزويج-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_018/01804.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":7597,"question":"يقول سؤاله الثاني والأخير: إذا كان الإنسان قد تزوج امرأة مشركة، وقد عاش معها سنتين هل يجوز أن يستمر معها أو أن يفارقها لعدم موافقتها في دينه، نرجو الإفادة وفقكم الله؟","title":"حكم نكاح المشركة","answer":"الجواب: المشركة فيها تفصيل: إن كانت وثنية، مثل مجوسية، مثل شيوعية، مثل وثنية تعبد القبور، هذه الزواج منها باطل، المسلم ما يحل له يتزوج المشركة، الله يقول سبحانه: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] ويقول سبحانه في المشركات: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]، ويقول: وَلا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ [الممتحنة:10] فالنكاح باطل، إذا كانت الزوجة مشركة وثنية من عباد القبور من عباد النار من الشيوعيين الملاحدة وأشباههم هؤلاء لا يحل للمرأة منهن للمسلم. \nأما إن كان قصده يهودية أو نصرانية من أهل الكتاب يعني، فهذه نكاحها صحيح إذا كانت محصنة معروفة بعدم الزنا، يعني غير مسافحة بل يهودية أو نصرانية لكنها معروفة بالحصانة وعدم بذل نفسها للزنا، فلا بأس، لأن الله أباح المحصنات من أهل الكتاب، فإذا تزوج محصنة من أهل الكتاب فلا بأس بذلك، وإذا كانت حالها لا تعجبه؛ لأنها قد تثبطه عن دينه أو تشككه في دينه أو ما أشبه ذلك فينبغي له تركها. \nوبكل حال: التزوج من الكتابية تركه أولى بكل حال؛ لأنها قد تجره إلى دينها، وقد تجر أولاده إلى دينها وأخلاقها، وقد تربيهم على الشر والكفر، فينبغي له أن لا يتزوجها وفي المسلمات غنية وكفاية بحمد الله، هذا هو الأولى بالمؤمن أن لا يتزوج من اليهود و النصارى ولاسيما في هذا العصر فإن اليهوديات و النصرانيات لهن نشاط في الدعوة إلى دينهم الباطل، ولهن نشاط أيضاً في الدعوة إلى الأخلاق المنحرفة وإلى الفواحش والمنكرات إلا من شاء الله، فينبغي التحرز من ذلك، وينبغي له أن يختار لزواجه المرأة الصالحة الطيبة من المسلمين، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4650/حكم-نكاح-المشركة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02005.mp3","categories":["نكاح الكفار"]},{"id":7801,"question":"سؤاله الأخير يقول فيه: ما حكم رجل زوج أخته أو بنته لرجل لا يصلي وهو يعلم بذلك، ولكن لظروف حصل هذا الزواج منها صلة القرابة وضغط من الأقارب وهل يأثم وليها؟","title":"حكم تزويج البنت لرجل لا يصلي","answer":"الجواب: من لا يصلي لا يجوز أن يزوج المسلمة؛ لأن ترك الصلاة كفر نعوذ بالله، فالذي لا يصلي لا يجوز تزويجه وأنت غلطان في هذا التزويج وآثم وعليك إثم كبير في تزويج ابنتك لإنسان لا يصلي هذا لا يجوز، الصواب عند أهل العلم المحققين أن ترك الصلاة كفر أكبر مخرج من الملة؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، في أحاديث أخرى دلت على ذلك.\nفالواجب عليك السعي في الفراق بينها وبينه إلا أن يتوب إن تاب إلى الله ورجع واستقام على الصلاة فلا بأس وإلا فالواجب عليك كما أدخلتها في هذا البلاء الواجب عليك أن تسعى في إخراجها والتفريق بينها وبينه؛ لأن هذا هو الواجب عليك وليس لها أن تزوج رجلاً كافراً لا يصلي، وليس لك أن تمكنها من ذلك أنت ولو شدد عليك الأقارب ليس لك ذلك، حق الله أكبر وحكم الله أولى بالمراعاة.\nفالحاصل عليك أن تخرجها من هذا البلاء كما أدخلتها فيه، وعليك أن تسعى في التفريق بينهما إلا أن يتوب، وإن تاب فلا بأس ببقائها ومن تاب تاب الله عليه، رزق الله الجميع الهداية والصلاح والعافية من كل سوء. نعم.","link":"https://binbaz.org.sa/fatwas/5162/حكم-تزويج-البنت-لرجل-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05010.mp3","categories":["نكاح الكفار"]},{"id":7840,"question":"ننتقل إلى رسائل أخرى من رسائل السادة المستمعين، فهذه رسالة الأخ أحمد شارع الروقي، وعبدالمجيد عبد الله شارع، الإخوان يسألون هذا السؤال هل يجوز للمسلم أو السعودي -لا أدري لماذا السعودي بالذات شيخ عبدالعزيز- بالخصوص أن يتزوج غير مسلمة؟ وجزاكم الله ألف خير.","title":"حكم زواج المسلم بغير المسلمة","answer":"الجواب: نعم يجوز للمسلم سعودياً أو غير سعودي، يجوز للمسلم أن يتزوج الكافرة الكتابية المحصنة، وهي التي لا تعرف بتعاطي الفواحش، هي الحرة العفيفة كما قال الله جل وعلا في كتابه العظيم : الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ [المائدة:5]، فالمحصنات من أهل الكتاب هن الحرائر العفائف، فيجوز للمسلم أن ينكح المحصنة من اليهود والنصارى، لكن تركها أولى وأفضل والاكتفاء بالمسلمات؛ لأن نكاحها قد يجر الزوج إلى دينها، وقد يجر أولادها إلى النصرانية واليهودية ؛ ولهذا كره ذلك جمع من الصحابة أصحاب النبي ﷺ وخافوا من ذلك، وإلا ..... هن حلال بنص القرآن الكريم، إذا كن محصنات عفيفات معروفات بالبعد عن الفواحش وعن الزنا حرائر لا مملوكات، فإنه يتزوجها المسلم ولو كان قادراً على مسلمة، لكن نكاحه للمسلمة أولى وأفضل وأسلم وأبعد عن الفتنة له ولأولاده، نعم.\nأما غير أهل الكتاب فلا، كالملاحدة من الشيوعيين أو الوثنيين كـالمجوس وأشباههم وشبههم من سائر الكفرة هؤلاء لا يجوز نكاح نسائهم، إنما هذا خاص بأهل الكتاب اليهود والنصارى ، أما بقية الكفار فلا يجوز للمسلم أن ينكح منهن أحدا، نعم.\nالمقدم: جزاكم الله خيرا، والأمر كما تفضلتم سماحة الشيخ هو مباح والحمد لله، لكن هل يشترط في الكتابية شروط معينة أو أن الأمر على الإطلاق؟\nالشيخ: مثلما قال الله: مُحْصَنَاتٍ غَيْرَ مُسَافِحَاتٍ [النساء:25]، لا يكن زواني، يكن معروفات بالستر والبعد عن الفاحشة، أما إن كن زواني مسافحات لا تنكح لا مسلمة ولا كافرة، لكن ينكحها إذا تأكد عن حالها وأنها محصنة يعني: عفيفة، فإذا تأكد عن حالها بشهادة العارفين بها تزوجها، ومع هذا كله فتركها أفضل، ولو كانت محصنة ولو كانت عفيفة، تركها أولى وأفضل؛ لأن هذا أسلم لدينه، لأنها قد يجره حبه لها إلى أن يعتنق دينها أو يتساهل في دينه، وقد يجر أولادها كذلك إلى أن يكونوا مع أمهم في اليهودية أو النصرانية ، وقد يطلقها وتذهب بأولاده إلى بلادها وإلى جماعتها.\nفالحاصل أن فيه خطر، أن فيه خطراً كما قاله الصحابة رضي الله عنهم، نعم.\nالمقدم: جزاكم الله خيرا، فيما يخص دينها شيخ عبد العزيز ؟\nالشيخ: دينها كافرة؟\nالمقدم: كافرة.\nالشيخ: نعم، سماهم الله كفار ...\nالمقدم: لكن هل يشترط عليها أن تكون ملتزمة بشيء من أحكام دينها؟\nالشيخ: كما قال سبحانه لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ [البينة:1] سماهم كفرة، فالمقصود أنهم كفرة، اليهود والنصارى كفرة والمشركون أيضاً، ولكن عند الإطلاق المشركون عباد الأوثان وأهل الكتاب هم اليهود والنصارى.\nوقد يطلق اسم الشرك على الجميع كما في قوله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا [التوبة:28] هذا يعم اليهود والنصارى وجميع المشركين ليس لهم أن يقربوا المسجد الحرام، ولكن يستثنى من المشركين أهل الكتاب، فلا مانع من نكاح نسائهم إذا كن محصنات معروفات بذلك وترك ذلك أفضل.\nوفي هذا العصر أشد وأشد؛ لأن ضعف الإيمان في الرجال، وكثرة الفتن في العصر الحاضر، وكثرة الدوافع إلى الميل إلى النساء، والسمع والطاعة للنساء، هذا يوجب الحذر ويشتد معه الخطر، فتركها بكل حال أفضل، نعم.\nالمقدم: جزاكم الله خيرا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/5232/حكم-زواج-المسلم-بغير-المسلمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_052/0052510.mp3","categories":["نكاح الكفار"]},{"id":7872,"question":"في سؤاله الأخير سؤال أحمد بن محمد اليحيى يقول: وردت أحاديث في الحضانة بأنه ﷺ قد جعل الابن مرة للأب ومرة للأم ومرة جعلهما يستويان، ومرة خير الابن، فما هو القول في هذه المسألة أعني القول الراجح؟","title":"إرجاع أمر حضانة الأبناء إلى القضاء","answer":"الجواب: هذه المواضع هذه مسائل الحضانة فيها خلاف بين أهل العلم وفيها أحاديث متعددة، فهي ترجع إلى العلماء القضاة وينظروا فيها عند الحادثة بما يدلهم الله عليه حسب ظاهر الأدلة، وحسب حال الزوج وحال الأم المرأة، فقد يكون الزوج صالحاً وهي غير صالحة، وقد تكون صالحة هي وهي أولى بالأولاد دونه لعدم صلاحه، فالمسائل هذه تحتاج إلى نظر وعناية، فالأولى أن تترك للقضاة حتى ينظروا فيها وقت حدوثها. نعم.","link":"https://binbaz.org.sa/fatwas/5323/ارجاع-امر-حضانة-الابناء-الى-القضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05610.mp3","categories":["حكم الصلاة وأهميتها","الحضانة","نكاح الكفار"]},{"id":7900,"question":"هذه رسالة وافتنا من عبادي الهباش من جدة الجامعة، يقول فيها: محمد سافر إلى الخارج لعدة شهور، وخوفاً من الوقوع في الحرام تزوج بامرأة وفي نيته تطليقها إذا أراد العودة إلى بلده، ما هو الحكم في ذلك، وما هو الحكم إذا لم تكن لديه نية مسبقة بطلاقها وأنجبت له طفل أو طفلة ثم طلقها؟","title":"حكم الزواج بنية جازمة للطلاق","answer":"الجواب: إذا نوى المسافر بزواجه أنه يطلق إذا عزم على الرحيل، هذا فيه اختلاف بين أهل العلم، من أهل العلم من ألحق هذا بالمتعة بنكاح المتعة، ومنهم من قال: لا يلحق بنكاح المتعة وليس منها في شيء؛ لأنه قد ينوي ولا يعزم، ليس بشرط، بخلاف المتعة فإنها مشارطة أنه يطلقها بعد شهر بعد شهرين يفارقها، أما هذا فليس بينه وبينهم مشارطة، إنما في قلبه ونيته أنه إذا أراد الرحيل مثلاً من أمريكا من لندن من كذا من كذا من المغرب من الجزائر طلق، وقد يفسخ هذه النية ويرغب فيها ويرتحل بها.\nفالأقرب والله أعلم أن هذا لا يكون من المتعة، قد يكون جائزاً ولكن الأولى ألا ينوي هذه النية، عليه أن يتزوج ناوياً إن ناسبته ارتحل بها وإلا طلقها.\nأما ينوي نية جازمة أنه يطلقها فالأولى ترك ذلك، خروجاً من خلاف العلماء، هذا هو الأولى، لكن لا يبطل النكاح ولا يكون متعة بهذه النية، هذا هو الصواب، إنما يكون نكاحاً ناقصاً؛ لأن في هذه النية والذي ينبغي أن يكون عليه الرغبة مطلقة، فإذا نوى أنه إذا أراد الرحيل طلق، فالصحيح أنه لا يبطل نكاحه لكنه ترك الذي ينبغي وهو أن ينوي نية مطلقة في الرغبة، إن ناسبته أبقاها وإلا طلقها، هذا هو الذي ينبغي للمؤمن.\nوأما إذا وقع الواقع ونكح مسلمة أو كتابية -يعني- محصنة بعيدة عن الفواحش، فإن الله إنما أباح لنا الكتابيات المحصنات، فإذا نكح كتابية محصنة جاز ذلك، والأولى البعد عن ذلك وترك ذلك؛ لأنها قد تجر عليه بلاء وقد تنجب له أولاداً وتنصرهم؛ فينبغي له الحذر من ذلك، وألا يتزوج إلا مسلمة.\nهذا هو الذي ينبغي حرصاً على سلامة دين أولاده بل على سلامته هو، فقد تجره إلى دينها وتنصره هي، فينبغي له الحذر، وقد يسلم هو ولكن لا تسلم ذريته؛ فينبغي له الحذر وألا يتزوج إلا مسلمة معروفة بالخير من بيئة صالحة؛ لأن هذا هو الذي يرجى فيه الخير، وترجى معه السلامة والإحصان. نعم.","link":"https://binbaz.org.sa/fatwas/5381/حكم-الزواج-بنية-جازمة-للطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06102.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":7907,"question":"سؤاله الأخير، سؤال الأخ المؤمن يقول: من له أولاد ومات عنهم، هل يبقون مع أمهم حتى ولو تزوجت أجنبياً أو أنهم يلحقون بأقاربهم كأعمامهم ونحوهم شرعاً، وهل لآراء الأطفال دور في هذا، أعني: هل لهم خيار بين أمهم وأقاربهم وفقكم الله؟","title":"حكم الطفل عند التنازع في حضانته","answer":"الجواب: هذه المسألة تحال للقضاة، إذا وقعت أمرها عند القضاة، أن المحاكم الشرعية تنظر في ذلك مع الزوجة أم الأطفال ومع أقارب الميت إذا تحاكموا إلى القضاة؛ لأنها تختلف المسائل هذه، نعم، تختلف والقضاة لهم النظر في هذا.","link":"https://binbaz.org.sa/fatwas/5405/حكم-الطفل-عند-التنازع-في-حضانته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06211.mp3","categories":["حكم الصلاة وأهميتها","الحضانة","نكاح الكفار"]},{"id":7922,"question":"ونبدأ يا سماحة الشيخ برسالة أحمد ضيف حسين من الجمهورية العراقية محافظة نينوى قضاء الشرقاط، يقول المستمع أحمد في رسالته، يقول: عندي ولد عمي توفي وعنده بنت، وبقيت هي ووالدتها في الدار بعد وفاته، يقول: وبعد وفاته تزوجت زوجته وأخذت زوجاً غريباً عن عشيرتي ولا من أقربائي، فأخذت البنت معها ولم تعطنيها وأنا أقرب الأقربين إليها، فذهبت إلى المحكمة الشرعية، فقدمت شكوى وجرت المرافعة بيني وبين أم البنت، والقاضي أعطى الحق إلى أم البنت، هل هذا صحيح، أرجو الحل السريع وشكراً، وأمد الله في عمركم؟","title":"مراعاة مصلحة الطفل عند التنازع في حضانته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفالحضانة للأطفال الصغار من الذكور والإناث تدور في الأغلب على رعاية المصلحة للطفل سواء كانت المصلحة في جانب الأم أو في جانب الولي الذي هو من جهة الأب، والقاضي هو الذي ينظر في هذه المسائل ويقدر المصلحة للطفل، وهذه القضية التي ذكرتها -أيها السائل- وهي كون ابن عمك توفي وخلف ابنة، وهذه الابنة تزوجت أمها ورأى القاضي أن تكون مع أمها هذه من جملة مسائل الحضانة التي ينظر فيها القاضي ويراعي الأصلح، فإذا رأى القاضي أن الأصلح بقاؤها مع أمها المزوجة فلا بأس ويقدم ذلك على ابن عمها، بل وعلى عمها، بل وعلى أبيها إذا رأى القاضي أن بقاءها مع أمها أصلح من تسليمها لأبيها لو كان موجوداً مطلقاً، مثل لو طلق أمها وكان موجوداً ورأى القاضي أن دفعها إلى أبيها لا يصلح؛ لفسقه وبدعته أو نحو ذلك، أو لأسباب أخرى، فهكذا من باب أولى إذا رأى ألا تسلم لعمها أو جدها أو ابن عمها، فبكل حال ينبغي لك يا أخي ألا تتأثر بهذا وأن تحسن الظن بما فعله القاضي، فهو إن شاء الله موفق؛ لأن وجودها عند أمها فيه مصالح كثيرة، ولاسيما إذا كان زوجها طيباً ولا يخشى منه عليها شر. نعم.","link":"https://binbaz.org.sa/fatwas/5421/مراعاة-مصلحة-الطفل-عند-التنازع-في-حضانته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_064/06401.mp3","categories":["حكم الصلاة وأهميتها","الحضانة","نكاح الكفار"]},{"id":8238,"question":"تقول: تقدم لها شاب هو ابن عمتها لكنه لا يصلي، بم تنصحونهم والحالة هذه شيخ عبد العزيز ؟","title":"هل يجوز تزويج التارك للصلاة؟","answer":"الجواب: أنصحها ألا تتزوج هذا الشاب؛ لأن من ترك الصلاة كفر - نسأل الله العافية- في أصح قولي العلماء؛ لقول النبي المصطفى عليه الصلاة والسلام في الحديث الصحيح الذي رواه مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة ، وروى الإمام أحمد في المسند وأصحاب السنن؛ أبو داود و الترمذي و النسائي و ابن ماجة بإسناد صحيح عن بريدة رضي الله عنه، عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ، في أحاديث أخرى تدل على كفر تارك الصلاة.\nفنصيحتي لهذه الفتاة ألا تتزوج هذا، وأن تلتمس رجلاً يخاف الله ويقيم الصلاة ويؤدي فرائض الإسلام، هذا هو الواجب عليها وعلى غيرها، وسوف يعوضها الله خيراً منه، فإن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وفي الحديث: من ترك شيء لله؛ عوضه الله خيراً منه فهي إن شاء الله على خير، ويرجى لها أن توفق لمن هو أصلح منه ولمن هو خير لها في دنياها وفي أخراها. نعم.","link":"https://binbaz.org.sa/fatwas/6050/هل-يجوز-تزويج-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09710.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8242,"question":"تقول: تقدم لها شاب هو ابن عمتها لكنه لا يصلي، بم تنصحونهم والحالة هذه شيخ عبد العزيز ؟","title":"هل يجوز تزويج التارك للصلاة؟","answer":"الجواب: أنصحها ألا تتزوج هذا الشاب؛ لأن من ترك الصلاة كفر - نسأل الله العافية- في أصح قولي العلماء؛ لقول النبي المصطفى عليه الصلاة والسلام في الحديث الصحيح الذي رواه مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة ، وروى الإمام أحمد في المسند وأصحاب السنن؛ أبو داود و الترمذي و النسائي و ابن ماجة بإسناد صحيح عن بريدة رضي الله عنه، عن النبي ﷺ أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ، في أحاديث أخرى تدل على كفر تارك الصلاة.\nفنصيحتي لهذه الفتاة ألا تتزوج هذا، وأن تلتمس رجلاً يخاف الله ويقيم الصلاة ويؤدي فرائض الإسلام، هذا هو الواجب عليها وعلى غيرها، وسوف يعوضها الله خيراً منه، فإن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وفي الحديث: من ترك شيء لله؛ عوضه الله خيراً منه فهي إن شاء الله على خير، ويرجى لها أن توفق لمن هو أصلح منه ولمن هو خير لها في دنياها وفي أخراها. نعم.","link":"https://binbaz.org.sa/fatwas/6050/هل-يجوز-تزويج-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_097/09710.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8283,"question":"الرسالة التالية باعثتها إحدى الأخوات من العراق بغداد تقول: إيمان كاظم جبار تقول: إنها شابة وموظفة وتبلغ من العمر ثمان وعشرين سنة وغير متزوجة، قدم لها شاب لا يعرف الكتابة ولا القراءة ويعمل نجارا، فقالت للشاب: روح تعلم كيف تكتب اسمك ثم تقدم للخطبة، وحينئذ عاد هذا فانتحر -كما تقول- وبدأ أصدقاؤها وأقرباؤها يلومونها على هذه اللفظة التي طلعت منها، حتى إن البعض قال: لقد ارتكبت رقبة، وهي الآن في قلق كبير، بم تنصحونها سماحة الشيخ؟","title":"حكم رفض المرأة الزواج من العامي الذي لا يكتب","answer":"الجواب: ليس عليك بأس يا أختي، ليس عليك بأس، نصحتِه يتعلم شيئاً من الكتابة وليس عليك بأس، وكونه انتحر هذا من سخافة عقله ومن جهله وقلة بصيرته، أنت ما قلت له إلا خيرًا، وتعلم الكتابة القليلة ميسرة، ميسر ليس بصعب، كونه يتعلم في الكتاب أو عند بعض أصحابه وإخوانه، كل هذا ميسر.\nفنصيحتك له إذا قلت له: تعلم الكتابة أو تعلم وتفقه في دينك، أو تعلم القرآن، كل هذا طيب ليس فيه شيء، وليس عليك بأس من ذلك، وإثمه عليه في انتحاره، أما أنت فليس عليك شيء واطمئني ودعي قول الناس.\nالمقدم: بارك الله فيكم. هنا رسالة وصلت إلى البرنامج من أحد الإخوة السودانيين: حيدر عبد الله أبو دياب يقول...\nالشيخ: نريد أن نزيدها.\nالمقدم: تفضل، تفضل.\nالشيخ: ونوصيك أيضًاً ونوصيك ألا تردِّي الطيب ولو كان عاميًّا لا يكتب ولا يقرأ، نوصيك في المستقبل، إذا خطبك الطيب المعروف بالاستقامة في دينه وصلاته وسمعته الحسنة فلا ترديه وإن كان لا يقرأ ولا يكتب، والنصيحة بعد ذلك بعد الزواج بينك وبينه، فلا تردي الطيب وإن كان لا يقرأ ولا يكتب، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6091/حكم-رفض-المراة-الزواج-من-العامي-الذي-لا-يكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10005.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":8284,"question":"الرسالة التالية باعثتها إحدى الأخوات من العراق بغداد تقول: إيمان كاظم جبار تقول: إنها شابة وموظفة وتبلغ من العمر ثمان وعشرين سنة وغير متزوجة، قدم لها شاب لا يعرف الكتابة ولا القراءة ويعمل نجارا، فقالت للشاب: روح تعلم كيف تكتب اسمك ثم تقدم للخطبة، وحينئذ عاد هذا فانتحر -كما تقول- وبدأ أصدقاؤها وأقرباؤها يلومونها على هذه اللفظة التي طلعت منها، حتى إن البعض قال: لقد ارتكبت رقبة، وهي الآن في قلق كبير، بم تنصحونها سماحة الشيخ؟","title":"حكم رفض المرأة الزواج من العامي الذي لا يكتب","answer":"الجواب: ليس عليك بأس يا أختي، ليس عليك بأس، نصحتِه يتعلم شيئاً من الكتابة وليس عليك بأس، وكونه انتحر هذا من سخافة عقله ومن جهله وقلة بصيرته، أنت ما قلت له إلا خيرًا، وتعلم الكتابة القليلة ميسرة، ميسر ليس بصعب، كونه يتعلم في الكتاب أو عند بعض أصحابه وإخوانه، كل هذا ميسر.\nفنصيحتك له إذا قلت له: تعلم الكتابة أو تعلم وتفقه في دينك، أو تعلم القرآن، كل هذا طيب ليس فيه شيء، وليس عليك بأس من ذلك، وإثمه عليه في انتحاره، أما أنت فليس عليك شيء واطمئني ودعي قول الناس.\nالمقدم: بارك الله فيكم. هنا رسالة وصلت إلى البرنامج من أحد الإخوة السودانيين: حيدر عبد الله أبو دياب يقول...\nالشيخ: نريد أن نزيدها.\nالمقدم: تفضل، تفضل.\nالشيخ: ونوصيك أيضًاً ونوصيك ألا تردِّي الطيب ولو كان عاميًّا لا يكتب ولا يقرأ، نوصيك في المستقبل، إذا خطبك الطيب المعروف بالاستقامة في دينه وصلاته وسمعته الحسنة فلا ترديه وإن كان لا يقرأ ولا يكتب، والنصيحة بعد ذلك بعد الزواج بينك وبينه، فلا تردي الطيب وإن كان لا يقرأ ولا يكتب، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6091/حكم-رفض-المراة-الزواج-من-العامي-الذي-لا-يكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10005.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":8323,"question":"بقي له سؤال في رسالته يقول: هل إذا تزوج رجل امرأة ظن أنها تقيم الصلاة، وتبين له بعد ذلك أنها لا تصلي، فهل هذا الزواج باطل، وهل إذا تابت وأصبحت تقيم الصلاة يستمر معها؟","title":"حكم الزواج بامرأة لا تصلي","answer":"الجواب: هذه المسألة مبنية على أصل وهو الحكم في تارك الصلاة، فمن قال: إنه كافر كفراً أكبر وإن لم يجحد وجوبها قال: إن هذا النكاح باطل؛ لأن الكافرة لا تصلح للمسلم، والله يقول في حقهن: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] وقال: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] فالتاركة للصلاة مشركة على القول الحق، فلا تنكح حتى تتوب إلى الله عز وجل؛ لقوله سبحانه: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221] ولقوله في سورة الممتحنة: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10].\nأما على القول الآخر وهو: أن تارك الصلاة تهاوناً وكسلاً ليس بكافر كفراً أكبر ولكنه كفر أصغر وعاصي وحكمه حكم أهل الكبائر، فعلى هذا القول يكون النكاح صحيحاً، ويكون له عذر إذا فارقها؛ لأن ترك الصلاة عيب عظيم.\nولكن الصواب أنه كفر أكبر، وأنها إذا كانت لا تصلي فهي كافرة فلابد من تجديد النكاح، إذا تابت ورجعت إلى الله لابد من تجديد النكاح، هذا هو الصواب؛ لأنها ليست كالكتابية، بل ترك الصلاة ردة، فلابد من توبة صادقة، توبة نصوح، فإذا تابت جدد نكاحها إذا رغب فيها، وإلا تركها ومتى خرجت من العدة ساغ لها أن تتزوج وينبغي له أن يطلقها طلقة واحدة خروجاً من الخلاف حتى لا يبقى هناك خلاف، وحتى تتزوج على بصيرة، فإن المسألة خلافية فإذا طلقها طلقة واحدة كان ذلك قطعاً للتعلق بها وقطعاً لتعلقها به، وخروجاً من خلاف العلماء القائلين بأن النكاح ليس بفاسد؛ لأن ترك الصلاة عندهم ليس بكفر أكبر.\nوالمقصود في هذا: بيان الحكم الذي هو أولى بالدليل وأحق بالدليل، ولا شك أنه القول بكفر تارك الصلاة كفراً أكبر إذا كان تركها تهاوناً غير جاحد لوجوبها، أما من جحد وجوبها فإنه يكفر بإجماع المسلمين كفراً أكبر نسأل الله العافية؛ لأنه مكذب لله ولرسوله عليه الصلاة والسلام، وإنما النزاع فيمن تركها تهاوناً وهو يؤمن بوجوبها هذا هو محل النزاع، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر رواه أهل السنن والإمام أحمد بإسناد صحيح، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، وهذا دليل على أن تركها كفر أكبر، نسأل الله السلامة. نعم.\nالمقدم: يعني: المستمع في هذه الحالة إن كان يرغب في البقاء معها فعليه أن يجدد عقد نكاحه؟\nالشيخ: بعد توبتها. نعم.\nالمقدم: جزاكم الله خير.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6140/حكم-الزواج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_202/20205.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8517,"question":"السائل: يقول: هذه الزوجة المعقود قراني عليها الآن لا تطيع أمري ولا تؤدي الصلاة، وكان هذا شرط لي قبل عقد القران، فبعد العقد تمردت علي، فتركتها منذ خمسة عشر شهراً، فما حكم الشرع في هذه الزوجة المتمردة علي، أفتوني؟","title":"حكم فراق الزوجة التاركة للصلاة","answer":"الجواب: التي لا تصلي لا تعتبر مسلمة بل تعتبر كافرة في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر؛ لأنها عمود الإسلام، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وهذا يعم الرجال والنساء، والصحيح أنه كفر أكبر، هذا هو الصواب، وهو الذي أجمع عليه أصحاب النبي ﷺ، كما قال عبد الله بن شقيق العقيلي: لم يكن أصحاب رسول الله ﷺ يرون شيئاً تركه كفر إلا الصلاة هذا يدل على أنهم أجمعوا على هذا ، فالتي لا تصلي لا خير فيها، بل عليك فراقها بالكلية، الله قال: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10] وقال: وَلا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ [الممتحنة:10] فهذه المرأة لا خير فيها بل يجب فراقها. نعم.\nالمقدم: جزاكم الله خير. وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6590/حكم-فراق-الزوجة-التاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20307.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8521,"question":"يقول: أنا متزوج اثنتين، ولكنهما لا تصليان، فقط تصومان شهر رمضان، وقد أمرتهن بالصلاة أكثر من مرة، فإحداهن صلت أياماً، وعندما رجعت من السعودية إلى مصر وجدتها قد تركت الصلاة، والثانية تقول: إنها لا تعرف شيئاً من القرآن حتى الفاتحة، فأفيدوني ماذا أفعل؟","title":"حكم الزوجة التي لا تصلي أو لا تعرف قراءة الفاتحة","answer":"الجواب: عليك أن تستتيبهما، وتبين لهما عظم شأن الصلاة وأنها عمود الإسلام، وأن تركها كفر، فإن تابتا فالحمد لله بقيتا معك، وإن لم تتوبا وجب عليك فراقهما، وسوف يعطيك الله خيراً منهما، فمن ترك شيئاً لله عوضه الله خيراً منه، والله سبحانه يقول: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] والجاهلة تعلم الفاتحة، تعلم السور القصيرة في الأوقات المناسبة التي يكون قلبها فارغاً حاضراً، تعلمها وتجتهد في ذلك، ولك أجر عظيم، وإذا عجزت عن الفاتحة، تأتي بدلاً منها بالأذكار تقول: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، حال قيامها في الصلاة، النبي صلى الله عليه وسلم أمر من عجز عن الفاتحة أن يأتي بهذا الذكر، فإذا عجزت تأتي بهذا الذكر، ولكن مع المحاولة إن شاء الله في الأوقات المناسبة إن شاء الله تحفظ تتعلم. نعم.\nالمقدم: جزاكم الله خير، يعني: الاستتابة لهما تكون بتأديتهما للصلاة يعني؟\nالشيخ: نعم.\nالمقدم: وإن لم تتوبا فعليه أن يفارقهما؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خير","link":"https://binbaz.org.sa/fatwas/6592/حكم-الزوجة-التي-لا-تصلي-او-لا-تعرف-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20309.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":8653,"question":"هذه رسالة وردتنا من السائل محمد السيد أحمد ، من مصر يسكن في العراق يقول في رسالته: أنا أعمل في العراق وأقوم من الصباح ولا أرجع إلا بعد المغرب، ولا يظل عندي وقت لأجل أن أصلي، ومكان الماء بارد جداً ولا أستطيع الوضوء فأؤجل الصلاة، فما الحكم في ذلك؟","title":"حكم من يؤجل الصلاة بسبب العمل أو برودة الماء","answer":"الجواب: الواجب على المسلم أن يتقي الله أينما كان، وأن يذكر أنه موقوف بين يديه سبحانه ومسئول يوم القيامة عما قصر فيه وعما ارتكبه من حرام وعما ضيعه من واجب، والله يقول سبحانه: يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لا يَجْزِي وَالِدٌ عَنْ وَلَدِهِ وَلا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ شَيْئًا إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ [لقمان:33] ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَلْتَنْظُرْ نَفْسٌ مَا قَدَّمَتْ لِغَدٍ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ خَبِيرٌ بِمَا تَعْمَلُونَ [الحشر:18] والصلاة هي عمود الإسلام، وهي أعظم واجب بعد الشهادتين، فلا يجوز للمسلم أن يضيعها في الوقت من أجل حظه العاجل ودنياه العاجلة.\nفيجب عليك -أيها السائل- أن تصلي الصلوات في أوقاتها، وليس لك تأخيرها من أجل أعمالك الدنيوية، بل عليك أن تصليها حسب الطاقة، فإذا استطعت أن تتوضأ بالماء ووجدت ماءً تستطيع الوضوء به ولو بالتسخين وجب عليك ذلك، فإن لم تجد إلا ماءً قد تناهى في البرودة لا تستطيع الوضوء به ولا تستطيع تسخينه بالنار فعليك أن تصلي بالتيمم في الوقت وليس لك التأجيل، عليك أن تصلي في الوقت ولو بالتيمم عند العجز عن الماء كالمسافر الذي يكون في البر ليس عنده ماء يتيمم ويصلي.\nأما تأجيل الصلاة من أجل الرفاهية أو من أجل الحظ العاجل من الدنيا والأعمال الدنيوية فهذا منكر عظيم وفساد كبير وخطر عظيم لا يجوز للمسلم فعله أبداً. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6789/حكم-من-يوجل-الصلاة-بسبب-العمل-او-برودة-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_213/21304.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":8901,"question":"هنا رسالة من السودان وباعثها أحد الإخوة من هناك يسأل في الواقع عن زوجته، أخونا يقول: إنه متزوج وزوجته لم تعرف ولا شيئًا من القرآن الكريم، ولم تقم الصلاة، وقد حاول فيها منذ عشر سنوات لكنها لم تستجب حتى الآن، ثم يقول أيضًا: إنها لا تلبس الزي الإسلامي، ولم تقبل له أي نصح أو توجيه حول هذا الموضوع وهو يستشير سماحتكم في أمرها؟","title":"حكم الزوجة التي لا تصلي ولا تلتزم بالحجاب","answer":"فالحاصل أن هذه المرأة علاوة على أنها لا تصلي مع ذلك أيضًا لا تلبس الزي الإسلامي؛ فهذا يدل على مرض في قلبها يميلها إلى الكفرة وزي الكفرة.\nفنصيحتي لك -أيها السائل- فراقها مادمت معها من مدة طويلة عشر سنين وأنت لم تنجح في نصيحتها ولا في توجيهها إلى الخير فماذا ترجو من ورائها؟ النساء كثير والحمد لله وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ففارقها وأبشر بالخير العظيم والعاقبة الحميدة، ومع هذا تسأل الله لها الهداية، نسأل الله لنا ولها الهداية، وإن نصحتها آخر شيء وبينت لها أنها إن لم تستجب فإنك سوف تفارقها فهذا لعله يجدي فيها بعض الشيء.\nالمقدم: بارك الله فيكم يذكر ارتباطه بالأولاد سماحة الشيخ.\nالشيخ: هو أحق بأولاده لا حضانة لها، مادامت بهذه الصفة لا حضانة لها هو أولى بأولاده بكل حال، هو أولى بأولاده وبقاء أولاده عندها يضرهم وربما جرتهم إلى شر كثير، فالحاصل أن المسلم هو أولى بأولاده مطلقا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7057/حكم-الزوجة-التي-لا-تصلي-ولا-تلتزم-بالحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_168/16803.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":9180,"question":"أيضًا تقول: عرفت من بعض المشايخ أن عقد النكاح لا يصح إذا كان الزوج وأبو الزوجة لم يصلوا حتى لو لم ينكروا وجوب الصلاة، وكان زوجي لا يؤدي الصلاة، وبعد رجوعي بفترة أصبح يداوم على الصلاة في المسجد مع الجماعة، أرجو من سماحة الشيخ إفتائي في هذه المواضيع؟","title":"حكم عقد نكاح من كان تاركًا للصلاة ثم حافظ عليها","answer":"الجواب: على كل حال هذا يرجع إلى المحكمة والمحكمة تنظر في الأمر؛ لأن قولها وحدها لا يكفي. المقدم: أيوه، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7340/حكم-عقد-نكاح-من-كان-تاركا-للصلاة-ثم-حافظ-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_180/18004.mp3","categories":["نكاح الكفار"]},{"id":9305,"question":"سؤالها الثاني: تقول: زوج خالتي تارك للصلاة رغم أنه حج إلى بيت الله، وقد ذكرت له خالتي ما سمعته من البرنامج من حكم تارك الصلاة تهاونًا من أنه يكون كافرًا كفرًا يخرج من الملة ولكنه ظل تاركًا للصلاة، وهي سكتت عن ذلك، فهل معاشرته لها حرام عليها؟ وهل تاركة الصلاة من النساء يجوز كشف الوجه أمامها باعتبار أنها كافرة بتركها للصلاة وخرجت عن ملة الإسلام، أفيدونا عن هذه القضايا وفقكم الله؟","title":"حكم معاشرة الزوج التارك للصلاة وكشف الوجه أمام الكافرة","answer":"الجواب: لا شك أن الذي يترك الصلاة كافر وإن لم يجحد وجوبها في أصح قولي العلماء؛ لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة والمرأة كذلك في الحكم الشرعي؛ لأن القاعدة الشرعية أن الأحكام التي تثبت للرجال تكون للنساء، وهكذا العكس؛ لأن الجميع مكلف، والرسول ﷺ بعث للجميع وهكذا قوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فالذي لا يصلي ليس لزوجته البقاء معه وهي مسلمة، ليس لها أن تبقى معه، بل عليها أن تفارقه وأن تمنعه من الاتصال بها حتى يتوب فيتوب الله عليه.\nوهكذا المرأة التي تترك الصلاة ليس لزوجها المسلم أن يبقى معها، بل يجتنبها حتى تتوب فإن تابت وإلا فارقها وسوف يعوضه الله خيرًا منها؛ لأن الله يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وهذه من المصائب العظيمة، ترك الصلاة من المصائب العظيمة.\nفالواجب على المسلمين جميعًا أن يحذروا ذلك وأن يتناصحوا في ذلك، وأن يهجروا من ترك الصلاة، وأن لا يقبلوا دعوته، وأن لا يسلموا عليه، وأن لا يردوا عليه السلام، وأن لا يدعوه إلى وليمة ولا غيرها، بل يجب أن يهجر كالبعير الأجرب، لا يقرب ولا يزار إلا للدعوة إلى الله، إذا كان للدعوة يدعى وينصح فلا بأس.\nوأما طرح الخمار عند الكافرة فلا بأس على الصحيح، سواء كانت تاركة للصلاة أو يهودية أو نصرانية أو وثنية، لا حرج على المسلمة أن تراها الكافرة ولا تحتجب منها، هذا هو الصواب، وهذا هو الصحيح من قولي العلماء أن التحجب إنما يكون عن الرجل الأجنبي أما عن المرأة فلا، أما قول الله سبحانه: أَوْ نِسَائِهِنَّ [النور:31] فالمراد: نساء بني آدم، فالمرأة لا يحتجب عنها على الصحيح وإنما يحتجب عن الرجل الأجنبي الذي ليس بمحرم، وأما المرأة فإنها من جنس المرأة وإن كانت كافرة لا حرج على المسلمة أن لا تحتجب عنها؛ لأن الرسول ﷺ لم يأمر نساءه أن يحتجبن عن اليهوديات اللاتي كن في المدينة ولا عن غيرهن من الوثنيات، ولا نعلم أن امرأة من أزواج النبي ﷺ أو بناته احتجبت عن امرأة كافرة.\nوقد ثبت في الصحيحين عن أسماء بنت أبي بكر رضي الله تعالى عنهما أن أمها وفدت إليها في المدينة في وقت الصلح بين الرسول ﷺ وبين أهل مكة وهي كافرة، جاءت تطلب من بنتها الرفد والمساعدة، فاستأذنت أسماء الرسول ﷺ في أن تصلها فقال النبي ﷺ: صليها ولم يأمرها أن تحتجب عن أمها لأنها كافرة، والقضايا في هذا كثيرة كلها دالة على أنه ليس على المرأة المسلمة أن تحتجب عن المرأة الكافرة، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7459/حكم-معاشرة-الزوج-التارك-للصلاة-وكشف-الوجه-امام-الكافرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18406.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","نكاح الكفار"]},{"id":9351,"question":"الرسالة التالية وصلت إلى البرنامج من المستمع محسن بن مشعل العتيبي من الرياض، أخونا يقول: تزوجت ابنة عمي في عام ألف وأربعمائة وكان عمرها آنذاك ثنتي عشرة سنة ولم تنجب أولادًا حتى الآن، وأنا أعاملها معاملة حسنة وهي تبادلني هذه المعاملة الحسنة بالمعاملة السيئة حتى أنها لا تقوم بالفرائض الصلاة، وقد نصحتها عدة مرات ولم تستجب بحجة أنها لا تزال صغيرة، وتقول: إنها ستقوم بواجب الصلاة عند بلوغها سن العشرين أو واحد وعشرين، وهي أيضًا لا تقوم بواجبها نحو الزوج ... ويستمر في الشكوى من هذه الزوجة وأهم ما في الموضوع: أنها كانت متربية على غير تأدية الصلاة ويرجو من سماحة الشيخ التوجيه؟","title":"حكم البقاء مع الزوجة التاركة للصلاة","answer":"الجواب: ما دامت بهذه الصفة فلا خير لك فيها، بل يجب أن تفارقها، وليس لك أن تستمتع بها وهي بهذا السن، ما دامت بلغت سن النساء المكلفات، أكملت خمسة عشر سنة، أو أتاها الحيض، أو أنزلت عند الجماع أو في الاحتلام، أو أنبتت الشعر المعروف عند الفرج -الشعرة- فهي بهذه الأمور الأربعة تكون بالغة بأي واحد منها، فإذا كانت لا تصلي فلا يجوز بقاؤها عندك بل يجوز إبعادها وعدم الاستمتاع بها حتى يمن الله عليها بالتوبة.\nولك أن تضربها على هذا وتؤدبها حتى تستقيم؛ لأن ضربها في هذا المقام مهم جدًا، ولعل الله يهديها بأسبابك، ومع ذلك لم تنجب فعيوبها كثيرة، هذه المرأة عيوبها كثيرة والسلامة منها خير لك في الدنيا والآخرة، ولا يجوز لك البقاء معها أبدًا إلا أن تتوب، نسأل الله أن يهديها ويردها للتوبة أو يبدلك خيرًا منها. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7515/حكم-البقاء-مع-الزوجة-التاركة-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_185/18507.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":9524,"question":"الرسالة الثانية في هذه الحلقة وردتنا من هاشم مجد الدين السليفاني من محافظة دهوك من الجمهورية العراقية، يسأل يقول: هل يستطيع المسلم أن يتزوج كتابية أي: يهودية ونصرانية وهي على دينها والمسلم على دينه؟","title":"حكم تزويج المسلم بالكتابية وضوابط ذلك","answer":"الجواب: نعم يستطيع إذا كانت محصنة إذا كانت اليهودية أو النصرانية محصنة معروفة بالسلامة من الفواحش واتخاذ الأخدان، فإن الله أباح ذلك كما قال سبحانه: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ [المائدة:5] فإذا كانت المحصنة يعني معروفة بالسلامة من اتخاذ الأخدان من الزنا وهي حرة لا رقيقة، فإنه لا بأس بنكاحها وقد كره جمع من السلف ذلك، منهم عمر  كان يكره نكاح الكتابيات؛ لئلا تجر المؤمن إلى دينها، وهكذا كره ذلك جمع من أهل العلم خشية أن يجر الزوج إلى دينه أو الذرية، فإذا تيسر للمؤمن نكاح المؤمنة فذلك أولى وأفضل وأحوط، فإن تزوج الكتابية المحصنة فعليه أن يتحرز من شرها عليه وعلى أولاده، وعليه أن يحرص على أن تدخل في الإسلام لعل الله أن يهديها بأسبابه هذا هو المعتمد في هذه المسألة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7692/حكم-تزويج-المسلم-بالكتابية-وضوابط-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_245/24504.mp3","categories":["نكاح الكفار"]},{"id":9784,"question":"هذه رسالة من (م. ح. ق) من الرياض، تقول فيها صاحبتها: أنا امرأة متزوجة من رجل لا يصلي، وقد أنجبت منه ولدين، وأنا امرأة أصلي وأحافظ على عبادتي، وقد دعوته للصلاة كثيراً إلا أنه كان يرفض ويقول لي: إن الدين معاملة وأخلاق وليس حركات ولا ركعات، وهو مستقيم في بقية أموره الحياتية، وسؤالي: هل بقائي مع هذا الرجل حلال أم حرام، علماً بأن افتراقي عنه يشتت أولادي ويهدم أسرتي، ولكن خوف الله يجعلني أسألكم وأريد أن أعرف حكم الله أفادكم الله؟","title":"حكم بقاء المرأة مع زوج يترك الصلاة","answer":"الجواب: لا يجوز البقاء مع هذا الرجل الذي لا يصلي؛ لأن هذا يدل على قلة دينه أو عدم دينه بالكلية، فالصلاة عمود الإسلام من تركها عامداً كفر.\nفالواجب البعد عن هذا وأن لا تمكنيه من نفسك، وأن تذهبي إلى أهلك أو تمنعيه من نفسك بالكلية، حتى يتوب إلى الله وحتى يصلي، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة رضي الله عنه.\nوروى مسلم في الصحيح عن جابر  عن النبي ﷺ أنه قال: بين الرجل وبين الكفر والشرك ترك الصلاة فالصلاة هي عمود الإسلام، فمن تركها عامداً كفر والعياذ بالله.\nأما الناسي فيقضي والنائم يقضي، لكن من تركها عمداً هذا كافر في أصح قولي العلماء.\nوذهب جمع من أهل العلم: إلى أنه لا يكفر بذلك كفراً أكبر، بل يكون كفره كفراً أصغر؛ لأنه الرسول سماه كافراً عليه الصلاة والسلام ولكنه قول ضعيف، قول مرجوح.\nوالصواب أنه كفر أكبر، قال عبد الله بن شقيق العقيلي : كان أصحاب النبي ﷺ لا يرون شيئاً تركه كفر من الأعمال إلا الصلاة فحكى عن الصحابة جميعاً أنهم يعتبرون ترك الصلاة كفراً، وظاهر ما نقله عنهم أنهم يعتبرونه كفراً أكبر.\nفالواجب عليك أيها الأخت في الله التخلص من هذا الرجل، وعدم تمكينه من نفسك وليس لك أن تبقي معه حتى يتوب إلى الله.\nوقوله: إن الدين المعاملة، كلام ليس بصحيح، بل حسن المعاملة من الدين ليس هو الدين، الدين حسن المعاملة مع الله ومع عباده، ما هو بالمعاملة فقط، حسن المعاملة وطيب المعاملة ومن حسن المعاملة أداء الصلاة، فإذا أراد بحسن المعاملة مع الله ومع عباده فلا تكون معاملة حسنة إلا بأداء فرائض الله وترك محارم الله.\nفمن ضيع فرائض الله أو ضيع الصلاة أو ركب المحارم فلم يقم بحسن المعاملة، ولم يأت بحسن المعاملة، فالدين: حسن المعاملة مع الناس في البيع والشراء والاتصال والصحبة ونحو ذلك، وحسن المعاملة مع الله بأداء فرائضه، ليس مجرد حسن معاملة مع الناس بس لا، بل لا بد من حسن المعاملة مع الله، بأداء فرائضه وترك محارمه .\nفالواجب عليك تقوى الله وأن تحذري من البقاء مع هذا الرجل، ونسأل الله له الهداية.\nأما إن جحد وجوبها وقال: ما هي بواجبة، أو استهزأ بالمصلين كفر إجماعاً، بإجماع المسلمين، إذا استهزأ بالمصلين أو جحد وجوبها كفر إجماعاً، نسأل الله العافية نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7956/حكم-بقاء-المراة-مع-زوج-يترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25909.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":10169,"question":"تقول: توفيت والدتي منذ خمسة عشر عاماً وتزوج أبي من أختها ومنذ أن تزوجها أبي وهي لا تصلي ولم أرها صلت ولو مرة واحدة رغم ما قلته لها من عقوبة تارك الصلاة، وهي لا تصلي كسلاً وتهاوناً، وتقول بتهاون شديد: صلي أنت نيابة عني، فماذا أفعل معها؟ وما هو حدود تعاملي معها؟ أرجو أن توجهوني جزاكم الله خيراً.","title":"حكم من تزوج بامرأة لا تصلي","answer":"الجواب: تقدم الكلام في هذا، الجواب السابق وأن الواجب الإنكار عليها وتعليمها وتوجيهها، وعلى الزوج أيضاً أن يؤدبها في ذلك حتى تصلي، وإذا كان حين العقد لا تصلي وجب تجديد العقد كما تقدم، إن كان هو يصلي وهي لا تصلي العقد غير صحيح على الصحيح، بعض أهل العلم يراه صحيحاً إذا كانت لا تنكر وجوبها ولكنها تساهل أو تكاسل، ولكن الصواب أنه -العقد- غير صحيح للأحاديث السابقة، فالواجب امتناعه منها حتى تصلي ويجدد العقد وإلا فليطلقها لأن هذه شرها كثير ولها حكم الكفرة لتركها الصلاة نسأل الله العافية، لكن إذا تابت فإنه يجدد العقد بمهر جديد وعقد جديد وحضرة شاهدين كما تقدم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8349/حكم-من-تزوج-بامراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30810.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":10175,"question":"من جمهورية مصر العربية المستمعة (ف. م. م) من دمياط، بعثت برسالة ضمنتها جمعاً من الأسئلة من بينها سؤال ملخصه أنها مخطوبة لابن عمها وترجو أن يكون قد تاب عما كان يرتكب من المعاصي كتركه للصلاة وهي تقول: إنها كانت تاركة للصلاة وغير محتجبة إلا أنها الآن احتجبت وبدأت تصلي، وترجو سماحة الشيخ التوجيه فيما ينبغي للمخطوبين أن يكونا عليه؟ جزاكم الله خيراً.","title":"حكم عقد النكاح بين رجل وامرأة لا يصليان","answer":"الجواب: إذا كنتما جميعاً حين النكاح لا تصليان فالنكاح صحيح كما لو كنتما تصليان النكاح صحيح، وعليكما تقوى الله والاستقامة على دينه، والتعاون على البر والتقوى، وسؤال الله التوفيق سبحانه وتعالى، هكذا المؤمن والمؤمنة يجتهدان في الاستقامة على أمر الله والمحافظة على دينه من الصلاة وغيرها، مع سؤال الله الثبات على الحق والإعانة على الخير، أما إن كان أحدكما حين النكاح لا يصلي والآخر يصلي فإن الراجح من قولي العلماء في هذا أن عليكما أن تعيدا النكاح؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء وإن لم يجحد التارك الوجوب، فإذا كان أحدكما يصلي والآخر لا يصلي عند عقد النكاح فإنه يجدد النكاح بعدما تبتما، بعدما تاب الذي لا يصلي وصلى يجدد النكاح بعقد جديد ومهر جديد وولي وشاهدي عدل يحضران النكاح، والمهر ولو قليلاً الذي ترضى به المرأة ولو قليلاً، ويجدد العقد من الولي يقول: زوجتك، وهو يقول: قبلت، بحضرة شاهدين عدلين، في الحال ما يحتاج تأجيل، متى علما الحكم الشرعي بادرا بعقد النكاح.. يمتنع عنها حتى يجدد النكاح، هذا هو الصواب في هذه المسألة. نعم.\nالمقدم: سماحة الشيخ! هما لا زالا في دور الخطبة، ويسألان عن الشروط الواجب اتباعها أو توفرها في كل من الخاطب والمخطوبة.\nالشيخ: إذا كان لم يتم النكاح ولم يتم العقد فعليهما جميعاً التوبة إلى الله من تقصيرهما، وأن يحافظا على الصلوات الخمس، فإذا علم كل واحد من صاحبه أنه مستقيم فليتزوجا، إذا علم الزوج أن المرأة مستقيمة وهي كذلك علمت أنه مستقيم الحمد لله، بعدين يجرى النكاح، أما ما دام أحدهما لا يصلي فلا يجرى النكاح بل يتوقف فيه حتى يعلم كل واحد صلاح صاحبه وأنه مستقيم، حتى لا يقدم أحدهما على ما يضره، فإذا كانت تشك فيه أو هو يشك فيها فلا ينبغي تعجيل العقد حتى يتم الاطمئنان والعلم بأنهما يصليان جميعاً وأن الحالة مستقيمة حتى يدخلا في العقد على بصيرة، الله جل وعلا قال في كتابه الكريم: وَلا تَنكِحُوا الْمُشْرِكَاتِ حَتَّى يُؤْمِنَّ [البقرة:221]، وقال: وَلا تُنكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا [البقرة:221]، وقال في الكفار مع المسلمين: لا هُنَّ حِلٌّ لَهُمْ وَلا هُمْ يَحِلُّونَ لَهُنَّ [الممتحنة:10]، وترك الصلاة كفر أكبر في أصح قولي العلماء وإن لم يجحد الوجوب التارك؛ لقول النبي ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر في أدلة أخرى، وهذه المسألة قد عمت بها البلوى في كثير من الناس، وعظمت المصيبة بترك الصلاة ولا حول ولا قوة إلا بالله من كثير من الناس.\nفالواجب على الخاطب أن يعتني بالمرأة حتى يعلم أنها تصلي، فلا يقدم إلا على بينة وعلى بصيرة، وهي كذلك الواجب عليها ألا تعجل حتى تعرف أنه طيب وأنه يصلي وأنه مستقيم، حتى يكون العقد على بينة وعلى حالة مرضية من الطرفين. أصلح الله حالهما جميعاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8346/حكم-عقد-النكاح-بين-رجل-وامراة-لا-يصليان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_308/30807.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":10236,"question":"هل يجوز لفتاة ملتزمة بدينها أن تتزوج من رجل غير مصلي مع وجود النية بدعوته للعبادة حتى تكسب الأجر والثواب؟","title":"حكم تزوج الفتاة برجل لا يصلي","answer":"الجواب: إذا كان لا يصلي ليس لها التزوج به، الذي لا يصلي كافر، ما يتزوج إلا كافرة ما يتزوج مسلمة؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، ولقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقوله عليه السلام: رأس الأمر الإسلام وعموده الصلاة، والله يقول جل وعلا: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ [البقرة:43]، ويقول جل وعلا: حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى [البقرة:238]، ويقول سبحانه: وَمَا أُمِرُوا إِلَّاا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5]، فالذي لا يصلي ليس لها أن تتزوج منه، وإذا كانت معه تفارقه، تذهب إلى أهلها وتتركه حتى يتوب أو يطلق، نسأل الله العافية والسلامة.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8404/حكم-تزوج-الفتاة-برجل-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27811.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":10560,"question":"السؤال الأخير لأخينا يقول: لي أخت زوجها والدي من ابن خالتي وكان عمرها اثنتين وعشرين سنة، وهي الآن أنجبت منه ولداً وبنتين إنما كانت تاركة للصلاة، ما حكم العقد، وكيف توجهوننا؟ جزاكم الله خيراً.","title":"حكم العقد لمن عقد على امرأة لا تصلي","answer":"الجواب: إذا كان زوجها مثلها يترك الصلاة فالعقد صحيح، كعقود بقية الكفار؛ لأن ترك الصلاة كفر في أصح قولي العلماء، للحديث الصحيح يقول ﷺ في الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه، ويقول عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح.\nفإذا كان الزوجان كلاهما لا يصلي فالعقد صحيح كما لو كانا يهوديين أو نصرانيين أو وثنيين، والنبي صلى الله عليه وسلم أقر الكفار على عقودهم، أما إن كان أحدهما يصلي والآخر لا يصلي، ولكن الذي لا يصلي لا يجحد وجوبها ولكنه يتكاسل فهذا فيه خلاف بين العلماء، فالأكثرون على أن العقد صحيح وأنه ليس بكافر كفراً أكبر، ولكنه كفر أصغر.\nوالقول الصحيح: أنه كفر أكبر وأن العقد غير صحيح، وأنه يجب فسخ النكاح ويجب عليه طلاقها أو يفسخ النكاح، من جهة الحاكم الشرعي؛ لأن الزوجة لا تصلح للمسلم، أن تكون زوجة وهي تترك الصلاة، لكن إن تابت فله أن يعقد عليها عقداً جديداً، إذا كان هو يصلي وهي لا تصلي، ...: له أن يعقد عليها عقداً جديداً إذا تابت، أما بدون توبة فإن العقد غير صحيح فاسد، وعليه أن يطلقها طلقة واحدة، أو يفسخها الحاكم حتى لا تبقى علقة بينهما ولا شبهة بينهما، ومتى تابت أمكنه أن يتزوجها من جديد بالشروط الشرعية.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8734/حكم-العقد-لمن-عقد-على-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32204.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":11299,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين، يقول: إنني متزوج، ورزقني الله بأولادٍ وبنات ولله الحمد، ولكن عندما تم العقد بيني وبين زوجتي كنا جميعًا لا نصلي، والآن هدانا الله إلى الطريق السوي، فماذا علينا؟ وهل العقد صحيح؟","title":"حكم عقد النكاح إذا كان الزوجان لا يصليان ثم تابا","answer":"الجواب:\n\nنعم، العقد صحيح، له حكم الصحة -والحمد لله- والتوبة تجبُّ ما قبلها، مثل الكافرين الآخرين إذا تزوج الوثنيان واليهوديان والنصرانيان، زواجهم صحيح إذا تمت شروطه، وهكذا من لا يصلي العقد صحيح إذا كانت الشروط ظاهرة، وهو لا يصلي وهي لا تصلي كلاهما سواء، فإذا تزوجها بالولي وليس هناك مانع -والحمد لله- إذا كانت الشروط متوفرة فالعقد صحيح، وإذا تابا تاب الله عليهما.\n\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9482/حكم-عقد-النكاح-اذا-كان-الزوجان-لا-يصليان-ثم-تابا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37614.mp3","categories":["نكاح الكفار"]},{"id":12155,"question":"تسأل أختنا فتقول: قد يحصل أن تتزوج الفتاة بتارك صلاة، وبعد الزواج تطلب من الزوج أن يعيد عقد النكاح، بعد أن تبينت توبته، لكن بعض الأزواج يرفض ذلك، فما هو توجيه سماحتكم؟ جزاكم الله خيرًا.","title":"حكم تجديد عقد الزواج للتائب من ترك الصلاة","answer":"الجواب:  يرفع الأمر للمحكمة، وتنظر المحكمة في هذا، يرفع الأمر إلى المحكمة إذا سمح أن يعيد النكاح؛ فلا بأس، وهذا أطيب وهذا هو الواجب، وإن لم يسمح؛ فالمحكمة تنظر في الأمر، نعم. المقدم: جزاكم الله خيرًا، إذًا لا يجوز السكوت على هذا؟ الشيخ: نعم، إذا كان تعلم المرأة أنه لا يصلي حين العقد، وهي تصلي؛ فإن العقد يجب تجديده، تجديد العقد من الولي الشرعي بعد توبة الزوج من ترك الصلاة، وهكذا العكس لو كانت هي ما تصلي، وهو يصلي؛ يجدد العقد أيضًا، أما إذا كانا لا يصليان جميعًا؛ فالعقد صحيح، لتساويهما في الباطل، نعم.","link":"https://binbaz.org.sa/fatwas/10340/حكم-تجديد-عقد-الزواج-للتاىب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_441/44105.mp3","categories":["نكاح الكفار"]},{"id":12245,"question":"هل يجوز أن يعقد العقد على زوجة لا تصلي؟","title":"حكم العقد على زوجة لا تصلي أو كتابية","answer":"الجواب:  إذا كان الزوج يصلي؛ فليس له أن يعقد عليها حتى تتوب إلى الله، أما إذا كان لا يصلي؛ فهو من جنسها، لكن إذا كان يصلي وهي لا تصلي؛ فليس له العقد عليها حتى تتوب، هكذا إذا كان لا يصلي، وهي تصلي، ليس لها أن تزوجه حتى يتوب إلى الله ويصلي؛ لأن ترك الصلاة كفر أكبر عند المحققين من أهل العلم، لقول النبي ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر ولأدلة أخرى من الكتاب والسنة تدل على كفر تارك الصلاة، فمن تركها من الرجال والنساء، -وإن لم يجحد وجوبها- كفر في أصح قولي العلماء، لكن إن جحد وجوبها، أو استهزأ بها؛ كفر عند الجميع، نعوذ بالله، إذا قال: ما هي بواجبة، أو استهزأ بها، وسخر منها، أو من أهلها؛ إنكارًا لها، واستهزاءً بها؛ كفر -نسأل الله العافية- عند جميع العلماء؛ لأن الله يقول سبحانه: قُلْ أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنتُمْ تَسْتَهْزِئُونَ ۝ لا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ [التوبة:65-66] ولأنه إذا جحد وجوبها؛ فقد كذب الله ورسوله؛ فيكون كافرًا، نسأل الله العافية.  وهكذا لو جحد وجوب الزكاة، أو جحد وجوب صوم رمضان، أو جحد وجوب الحج مع الاستطاعة، أو استهزأ بذلك؛ كفر عند جميع المسلمين، وهكذا لو جحد تحريم الزنا قال: الزنا حلال، أو الخمر حلال وهو مثله لا يجهل ذلك، أو علم وبين، ثم أصر على جحد تحريم الزنا، أو جحد تحريم الخمر؛ يكون كافرًا، نسأل الله العافية. والحاصل أن كل من أنكر ما أوجب الله مما هو معلوم عند الجميع كالصلاة والصوم ونحو ذلك، أو أنكر تحريم ما حرمه الله مما هو معلوم عند جميع أهل العلم، معلوم بالنصوص، كالزنا، والخمر؛ فإن هذا يكون كافرًا عند جميع العلماء نسأل الله العافية، ومثل ذلك من ترك الصلاة، وإن لم يجحد وجوبها؛ فهو كافر في أصح قولي العلماء؛ لأن الصلاة أمرها عظيم، ليست من جنس غيرها من الواجبات، بل هي أعظم الواجبات، وأهمها بعد الشهادتين، فتركها والتساهل بها ليس من جنس غيرها، بل يكون صاحب ذلك كافرًا -نسأل الله العافية- من الرجال والنساء، نعم.  المقدم: جزاكم الله خيرًا، حدثوني لو تكرمتم عن حكم الزواج بالمسيحية؟  \nالشيخ: يجوز للمسلم أن ينكح المسيحية، واليهودية إذا كانت محصنة، غير معروفة بالسفاح، بالزنا، قال سبحانه: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ [المائدة:5] فإذا تزوجها وهي محصنة، غير مسافحة، معروفة بالستر، وعدم الزنا؛ فإنه يجوز له أن ينكحها مسلم، لكن تركها أفضل، والحرص على المسلمة أسلم له ولذريته؛ ولأنها قد تجره إلى الكفر، أو تجر ذريته، فالأولى بالمؤمن ألا ينكح الكتابية، وأن يعدل عنها إلى المسلمة؛ احتياطًا لدينه، وخوفًا على نفسه وذريته، نسأل الله السلامة والعافية، نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10434/حكم-العقد-على-زوجة-لا-تصلي-او-كتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_448/44809.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":13475,"question":"تسأل أختنا سؤالها الأخير في هذه الحلقة وتقول: ما رأيكم إذا كان الزوج لا يصلي، أو الزوجة لا تصلي والزوج يصلي، ما الأذى على من يصلي والحال ما ذكر؟ جزاكم الله خيرًا.","title":"ما حكم النكاح إذا كان أحد الزوجين لا يصلي؟","answer":"الجواب: إذا تزوج إنسان امرأة، ثم بان بعد الزواج أن أحدهما لا يصلي؛ يفسخ النكاح؛ لأن من لا يصلي كافر على الصحيح من أقوال العلماء، ولو لم يجحد الوجوب، ولو كان كسلًا، ترك الصلاة كفر أكبر -نسأل الله العافية- في أصح قولي العلماء، فإذا كان لا يصلي؛ فسخ النكاح، أو كانت هي لا تصلي وهو يصلي؛ فسخ النكاح، أما إن كانا لا يصليان جميعًا؛ فالنكاح صحيح كسائر الكفرة، كنكاح سائر الكفرة. أما إذا كان أحدهما يصلي والآخر لا يصلي؛ فإنه يفسخ النكاح حتى يتوب من لا يصلي، فإذا تاب ورجع؛ جدد النكاح له عليها إذا رضيت بذلك، وإن كانت هي التي لا تصلي، فإذا تابت ورجعت؛ جدد لها النكاح عليه إذا رغب في ذلك. والدليل على هذا قول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر وقوله ﷺ: بين الرجل، وبين الكفر والشرك ترك الصلاة مع أدلة أخرى في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/11778/ما-حكم-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47804.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":13675,"question":"سماحة الشيخ بعد ذلك ننتقل إلى الأردن والسائل محمود محمد يقول في هذا  هل يحل للرجل المسلم أن يتزوج من امرأة مشركة كتابية يهودية كانت، أو نصرانية؟ جزاكم الله خيرًا.","title":"حكم الزواج بالكتابية","answer":"الجواب: يجوز الزواج من اليهودية، والنصرانية أهل الكتاب إذا كانت محصنة عفيفة معروفة بالعفة وحرة؛ لقول الله -جل وعلا- في سورة المائدة: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ [المائدة:5]. فإذا كانت محصنة عفيفة، وتزوجها الرجل العفيف؛ فلا بأس، ولكن كونه يتزوج من المسلمات أولى وأبعد وأحوط عن الشر، كونه يأخذ مسلمة أسلم؛ لأنها قد تضر أولادها، وقد تدعوهم إلى دينها الباطل، فكونه يتزوج مسلمة حنيفية -يعني: على دين الإسلام- أولى من تزوجه بكتابية، وإن كانت مباحة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12021/حكم-الزواج-بالكتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51907.mp3","categories":["نكاح الكفار"]},{"id":14049,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أحمد محمد علي سوداني وعمره خمس وعشرون سنة وعنوانه في العراق، أخونا له بعض الأسئلة، فيسأل في أحد أسئلته عن حكم تزوج الرجل المسلم بامرأة مسيحية، ويرجو التفصيل من سماحة الشيخ.","title":"حكم زواج المسلم بالمسيحية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد بين الله  في كتابه الكريم في سورة المائدة حل الزواج من محصنات أهل الكتاب، كما قال جل وعلا في كتابه العظيم: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ[المائدة:5].  فأباح سبحانه المحصنات من أهل الكتاب وهم اليهود والنصارى، والمحصنة: هي العفيفة، الحرة العفيفة هي المحصنة، فإذا كانت معروفة بالعفة والبعد عن الفواحش فإنه يجوز للمسلم نكاحها، أما إذا كانت لا تعرف بذلك فلا يحل نكاحها، أو معروفة بالفحش والفساد فلا يجوز نكاحها، وإن كانت كافرة لكنها مستثناة، المحصنة من اليهود والنصارى مستثناة من المسلمين إذا كانت محصنة، والمحصنة - كما تقدم - الحرة العفيفة التي لا يعرف عنها تعاطي الفواحش يعني: الزنا، فهي محصنة عفيفة بعيدة عن تعاطي الفواحش وإن كانت على دينها على دين النصرانية، ولكن نكاح المسلمات أولى وأفضل وأحق وأحسن وأبعد عن الشر ولاسيما المسلمات المعروفات بالديانة والاستقامة فإن زواجهن أفضل بكثير وأولى بكثير وأبعد عن الخطر.\nفنصيحتي لإخواني جميعًا الحرص على الزواج من المسلمات الطيبات وعدم الزواج من المحصنات من أهل الكتاب؛ لأن في ذلك خطرًا من جهة تنصير أولاده ومن جهة عدم عفتها أيضًا ولو تظاهرت بخلاف ذلك، نسأل الله للجميع العافية والسلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، سماحة الشيخ في حالة وقوع ذلك بم تنصحون الزوج؟\nالشيخ: إذا كانت محصنة ولا رأى منها إلا الخير فلا بأس بذلك، فلا بأس ببقائها، وأما إن شك فيها أو رأى منها ما يريبه فينبغي له طلاقها.\nكذلك إذا تيسرت له امرأة صالحة مسلمة فإن الأولى والأحق به أن يتزوجها ويطلق تلك حرصًا على سلامة دينه ودين أولاده، فإن الأولاد على خطر من ذهابهم مع أمهم عند أقل خلاف أو عند موت الزوج أو عند الفرقة بينه وبينها فالخطر قائم، ولا حول ولا قوة إلا بالله.\nالمقدم: الله المستعان، جزاكم الله خيرًا، كأن الحدود ضيقة في إباحة الزواج بغير .... ؟\nالشيخ: نعم نعم، ولهذا كره بعض الصحابة ذلك، كان عمر يكره ذلك ويرغب الصحابة في ترك ذلك رضي الله عن الجميع. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12479/حكم-زواج-المسلم-بالمسيحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61301.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":14434,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ع. ق) من الدمام، أخونا له عدد من الأسئلة فيسأل في سؤاله الأول ويقول:إذا تزوج الإنسان وهو لا يصلي، لا هو ولا الزوجة، وبعد الزواج بمدة طويلة هداهم الله للصلاة والأمور الشرعية، وفي وقت العقد اكتشف أنه كان محدثًا حدثًا أكبر، ولم يغتسل وقت العقد، بل أجرى العقد وهو على ذلكم الحال، هل العقد صحيح، أم بماذا تنصحونه حيال ما ذكر؟جزاكم الله خيرًا.","title":"حكم العقد إذا كان الزوجان لا يصليان","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإذا كان الرجل والمرأة حين العقد لا يصليان، فالعقد صحيح؛ لأنهما مستويان في ترك الصلاة، وفي الكفر عند من كفرهما بذلك وفي عدمه، فالنكاح صحيح، والصواب أن ترك الصلاة كفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولم يقل: بشرط جحدهما الوجوب، بل أطلق -عليه الصلاة والسلام-، فدل على أن من ترك الصلاة كفر، وإن أقر بالوجوب، ومن ذلك قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، لكنهما مستويان لا يصليان، فالعقد بينهما صحيح كالنصرانيين واليهوديين والوثنيين إذا تزوجا؛ لأنهما مستويان في عدم الدين. أما إذا كان أحدهما يصلي والآخر لا يصلي حين العقد فإن الواجب تجديد العقد بعدما صلى من لا يصلي وتاب إلى الله  يجدد العقد على الصحيح على القول بأن ترك الصلاة كفر أكبر، فيجدد العقد بمهر جديد، وشاهدي عدل، وبواسطة الولي، فالعقد يحضره أربعة: الولي والزوج والشاهدان، فيجدد العقد بمهر وشاهدي عدل بعدما تاب الله على من كان لا يصلي منهما، والحمد لله احتياطًا وخروجًا من خلاف العلماء الذين كفروا تارك الصلاة، وقولهم أصح لظاهر الأدلة الشرعية. وأما كونه تزوج على غير طهارة فهذا لا يضر العقد، وهكذا لو كانت المرأة على حيض حين العقد أو في نفاس لا يضر إذا كانت ليست في عدة، كالبكر عقد عليها وهي في الحيض أو امرأة قد خرجت من العدة عقد عليها وهي في الحيض لا يضر ذلك، ليس من شرط العقد أن يكون الرجل طاهرًا أو المرأة طاهرة، فإذا تم العقد والرجل على جنابة أو المرأة على جنابة أو في حيض أو في نفاس فالعقد صحيح ليس من شرطه الطهارة ما دامت ليست في العدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12909/حكم-العقد-اذا-كان-الزوجان-لا-يصليان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62401.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":14455,"question":"في سؤال طويل حول زوجها أيضًا تذكر أنه لا يصلي حتى الآن، وتسأل في النهاية: هل على المرأة المسلمة أن تنفصل عن الرجل الذي لا يصلي؟","title":"هل تنفصل المرأة عن الزوج الذي لا يصلي؟","answer":"الجواب: نعم عليها أن تنفصل؛ لأن ترك الصلاة ردة، كفر أكبر في أصح قولي العلماء، وقد تقدم قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وقوله ﷺ: رأس الأمر الإسلام، وعموده الصلاة إذا ضيع الصلاة ويش بقي عنده، نسأل الله السلامة، من ضيعها ضاع، وكان عمر  يكتب إلى عماله ويقول: «إن أهم أمركم عندي الصلاة، فمن حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع».\nويقول : «لا حظ في الإسلام لمن ترك الصلاة» وقد جاء هذا المعنى مرفوعًا إلى النبي ﷺ: لا حظ في الإسلام لمن ترك الصلاة. فالحاصل: أنّ من ضيع الصلاة فلا دين له، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12932/هل-تنفصل-المراة-عن-الزوج-الذي-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48807.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":14535,"question":"رسالة وصلت إلى البرنامج من العراق، باعثتها إحدى الأخوات المستمعات تقول: (م. ن) في بداية رسالتها تقول: إني مواطنة مسلمة من القطر العراقي الشقيق، لا أزال غير محجبة، ولكن ملابسي محتشمة، وإني موظفة في إحدى المؤسسات، وأختلط بالرجال، زملاء لي في العمل ومواطنين لديهم مصالح تقتضي مقابلتهم في مؤسستنا.وإنني -والحمد لله- أؤدي فريضة الصلاة، وأصوم شهر رمضان منذ حوالي سبعة أشهر فقط، لم أكن في السابق من المصلين. أرجو إفادتي -حفظكم الله-: هل يصح عملي -أي الصلاة والصوم- بدون حجاب؟علمًا أني أنوي ارتداء الحجاب الإسلامي خلال فترة قريبة.","title":"حكم صلاة وصوم من لا ترتدي الحجاب","answer":"الجواب: الحمد لله الذي منَّ عليك بالتوبة، وقمت بالصلاة، هذه أعظم النعم؛ لأن ترك الصلاة كفر أكبر نسأل الله العافية، فنوصيك بالثبات على الحق، ولزوم ما أوجب الله عليك، وترك ما حرم الله عليك، ومن ذلك الحجاب، فإنه يجب على المرأة أن تحتجب عن الرجال، قال الله تعالى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] فالحجاب أطهر لقلبك وقلب الرجال، فنوصيك بلزوم الحجاب، والحذر من مخالطة الرجال، وأن يكون عملك مع النساء، أو في محل مستقل وحدك دون الرجال، ولا تختلطي بالرجال؛ فإن ذلك من أسباب الفتنة، وعليك التوبة مما مضى، ومن تاب تاب الله عليه، والتوبة الندم على الماضي، والإقلاع من الذنب، والعزم على عدم العود إليه عزمًا صادقًا، بنية الإخلاص لله، ومحبته وتعظيمه. وما فعلت من الأعمال الطيبة فهو صحيح من صلاة وصوم لا يبطله عدم الحجاب، عدم الحجاب لا يبطل الأعمال لكنه معصية، فعليك التوبة إلى الله من ذلك، والاستقامة على الحجاب في الطريق، وعند الرجال أينما كنت؛ ولهذا يقول : يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا[الأحزاب:59] ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا[النور:31] وما ظهر منها هي الملابس الظاهرة كالعباءة والجلباب ونحو ذلك. وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ[النور:31] والجيب مخرج الرأس، والمعنى: تضرب بالجلباب على رأسها ووجهها وصدرها حتى لا يبين منها شيء عند الرجال، ثم قال مؤكدًا سبحانه: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ[النور:31] والبعولة: الأزواج: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ ..[النور:31] الآية. فعليك أن تتقي الله في هذا الأمر، وأن تحذري التساهل في أمر الحجاب، رزقنا الله وإياك الاستقامة والهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13030/حكم-صلاة-وصوم-من-لا-ترتدي-الحجاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63412.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","نكاح الكفار"]},{"id":14601,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. ك. ع) من السودان الخرطوم، يقول: أنا من أسرة أجداد والدي لم يكونوا مسلمين، بل كانوا يعبدون الأوثان، وعلى ذلك تزوج والدي على غير كتاب الله وسنة رسوله ﷺ، وأنجبنا نحن، ولكن لحسن حظنا نشأنا في بيئة مسلمة، ودخلت المدرسة في وسط تلاميذ وأساتذة مسلمين، ومنذ الصغر تعلمنا في المدرسة قراءة القرآن، والصلاة، وإن تخلل ذلك بعض التهاون بالصلوات، ولكن في نهاية الأمر هداني ربي والتزمت بسنة نبينا محمد ﷺ منذ عدة سنوات، والحمد لله.وسؤالي هو: هل إسلامي هذا صحيح؛ وذلك لأنني مارست بعض الطقوس والعادات على طريقة أجدادي وكان ذلك فقط من باب حب الاستطلاع؛ ولجهلي بحرمتها، كما أن والدي كان غير مسلم، والدي الآن يصلي ويصوم، وترك العادات والطقوس غير الإسلامية؛ وذلك بدون أية مقدمات كإشهار الإسلام؛ لأنه كان يعيش ومنذ فترة طويلة في وسط مسلم، ولكنه كان يمارس الطقوس غير الإسلامية، كما وأنه كان يصلي ويصوم في نفس الوقت، ولكن في نهاية الأمر ترك الطقوس غير الإسلامية، وبدأ الصلاة والصوم وغيرها من الشعائر الإسلامية، هل إسلامه صحيح بالرغم من تركه الإشهار، وعدم الاغتسال الخاص بدخول الإسلام؟ماذا على والدي بخصوص زواجه الذي كان في السابق بدون إسلام، وعلى غير سنة النبي ﷺ؟وجهوني في هذه القضايا. جزاكم الله خيرًا.","title":"هل يلزم تجديد أنكحة من أسلم من الكفار؟","answer":"الجواب: الحمد لله، ما دام حصلت التوبة والرجوع إلى الله، والاستقامة منك ومن والدك، فالحمد لله.  أما الأنكحة الماضية فلا ينظر إليها؛ لأنها على طريقتهم، والكفار إذا أسلموا أقروا على أنكحتهم، فلا ينبغي النظر في ذلك، بل ينبغي النظر في الوقت الحاضر، فإذا تاب المؤمن تاب الرجل مما عنده من طقوس مخالفة للشرع، أو أعمال مخالفة للشرع كفى، والحمد لله.  فعليك لزوم التوبة، وعلى أبيك لزوم التوبة، وما دامت الزوجة صالحة ليست أختًا له ولا عمة له، وإنما قد يكون في بعض الطقوس عندهم خلل، فالحكم في ذلك أنها تقر على ما هي عليه كسائر أنكحة الكفار، ولا ينظر فيها بعد ذلك، يقرون على إسلامهم، وعلى أنكحتهم، كما أقر النبي ﷺ من أسلم يوم الفتح وغيره على أنكحتهم، ولم يغيرها، لكن لو فرضنا أنه بان له أنه تزوج أختًا له من الرضاعة، أو عمة له من الرضاعة، أو بنت أخيه من الرضاعة، فإنه يفارقها بعد إسلامه؛ لأن المانع موجود.  أما إذا كان الخلل في شيء من العقد بعدم الولي، أو ما أشبه ذلك فإنهم يقرون على أنكحتهم، نعم. المقدم: جزاكم الله خيرًا، ماذا عن الغسل سماحة الشيخ، يقول: إن والده عندما دخل الإسلام لم يغتسل؟ الشيخ: الغسل مستحب سنة، وليس بلازم. المقدم: وليس بواجب؟ الشيخ: نعم. المقدم: إذًا ليس عليه شيء؟ الشيخ: ليس عليه شيء، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13099/هل-يلزم-تجديد-انكحة-من-اسلم-من-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63601.mp3","categories":["نكاح الكفار"]},{"id":14657,"question":"المستمع (ح. س. ن) من سوريا، بعث برسالة يقول فيها: توفيت زوجتي وهي تلد، وكثير من الناس عندنا يقولون: إنها شهيدة، والشهيد إلى الجنة، مع أن زوجتي لا تصلي، هل تعتبر من الشهداء؟","title":"حكم من توفيت في الولادة وهي لا تصلي","answer":"الجواب: الموت بسبب الولادة شهادة جاء بذلك بعض الأحاديث عن رسول الله ﷺ إذا ماتت المرأة بسبب الولادة، لكن التي لا تصلي ليست مسلمة، والشهادة إنما هي للمسلم، فالتي لا تصلي جاء في النص عن النبي ﷺ أنه كافر، قال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وهذا هو الأصح من قولي العلماء أن الذي يتعمد ترك الصلاة، ولا يصلي لا يعتبر مسلمًا، سواء كان رجلًا أو امرأة، فلا يصلى عليه، ولا يدفن مع المسلمين، ولا يغسل، ولا يكفن؛ لأنه ترك عمود الإسلام، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13161/حكم-من-توفيت-في-الولادة-وهي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63703.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":15055,"question":"هل المرأة التي تزوجها الرجل وهي لا تصلي، وعندما تزوجها عرفها أمور دينها، وصلت والحمد لله، فهل في هذا شيء من الناحية الزوجية والأولاد؟","title":"حكم من تزوج بامرأة لا تصلي ثم تابت","answer":"الجواب: نعم إذا كان الزوج يصلي وهي لا تصلي يجدد النكاح، هذا هو الصواب، وذهب الأكثرون إلى أنه لا يجدد إذا كان لا يجحد وجوبها، إذا كانت لا تجحد وجوبها، وإنما هو تهاون منها، ولكن الصواب أنه يجدد النكاح؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر وهذا يعم الرجال والنساء، فإذا كانت لا تصلي وهو يصلي يجدد النكاح، وهكذا العكس، لو كان لا يصلي هو وهي تصلي يجدد النكاح. أما إن كانا لا يصليان جميعًا حين الزواج، فالنكاح صحيح، مثل بقية الكفرة، نكاحهم صحيح، وإذا تاب الله عليهما فالنكاح على حاله، أما إذا كان أحدهما لا يصلي والثاني يصلي فإنه يجدد النكاح؛ لأن الذي لا يصلي كافر، والكافر لا يصح له نكاح المسلمة، والمسلمة لا يصح لها نكاح الكافر، فلا بد من كونهما مسلمين أو كافرين. إلا إذا كانت المرأة من أهل الكتاب، كتابية يهودية أو نصرانية محصنة، جاز أن ينكحها المسلم؛ لأن الله أباح لنا نساء أهل الكتاب المحصنات، أما إذا كانت زوجته كافرة تترك الصلاة، فالنكاح حينئذٍ غير صحيح، أو كانت كافرة بعبادة القبور والاستغاثة بالأموات ونحو ذلك، فإن نكاحها باطل حينئذٍ، فعليه أن يجدد النكاح إذا كان مسلمًا. والحاصل والخلاصة: أنه إذا كانا كافرين، أو مسلمين جميعًا، فالنكاح صحيح، أو كان مسلمًا هو والمرأة كتابية فالنكاح صحيح، أما إذا كان كافرًا وهي مسلمة، فالنكاح باطل، أو كان مسلمًا وهي كافرة، لكنها غير كتابية، كالتاركة للصلاة وكالوثنية يكون النكاح غير صحيح أيضًا، نسأل الله السلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13546/حكم-من-تزوج-بامراة-لا-تصلي-ثم-تابت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49313.mp3","categories":["نكاح الكفار"]},{"id":15641,"question":"أريد أن أتزوج فما هو رأي سماحتكم في الشروط التي اشترطها في المخطوبة، ما هي؟وجهوني، جزاكم الله خيرًا.","title":"صفات الزوجة التي ينبغي اختيارها","answer":"الجواب: عليك بذات الدين، عليك بالمرأة الصالحة المعروفة بالأخلاق الطيبة، بالصلاة والعفاف، وطيب الخلق، وطيب الكلام، وحسن الصورة أيضًا؛ لقوله ﷺ: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها؛ فاظفر بذات الدين تربت يداك. فأوصى بذات الدين، فنوصيك بما أوصى به النبي ﷺ، ذات الدين، نوصيك بالمرأة المعروفة بالاستقامة بالصلاة في وقتها بالعفة عما حرم الله، بطيب اللسان، وطيب الكلام، بالأخلاق الكريمة، وحسن الخلق، وإذا تيسر مع هذا الجمال والنسب الحسن والمال؛ هذا خير إلى خير، ولكن المهم أن تكون أخلاقها كريمة، محافظة على الدين، طيبة في الصلاة، طيبة في أخلاقها، بعيدة عما حرم الله من الفواحش، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14181/صفات-الزوجة-التي-ينبغي-اختيارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70509.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":15895,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة في أحدها يقول: إذا تزوج الرجل بامرأة وهو لا يحافظ على الصلاة حفاظًا تامًا، بمعنى أنه يصلي فرضًا، ويترك آخر، ثم إنه بعد ذلك تاب وحافظ على الصلاة، هل يلزمه إعادة كتابة العقد -عقد الزواج- أم أن ما مضى صحيح؟جزاكم الله خيرًا.","title":"يجدد عقد الزواج للمتساهل في أداء الصلاة","answer":"الجواب: إذا كان الزوج لا يصلي بعض الأحيان أما الزوجة فهي محافظة، فإن عليه أن يعيد العقد في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء.  وذهب الأكثرون: إلى أنه لا حاجة إلى إعادة العقد إذا كان لا يجحد وجوبها، بل يعلم أنها فرض عليه، ويؤمن بذلك، ولكنه يتساهل في بعض الأحيان، يقولون: لا يلزمه تجديد العقد؛ لأنه لا يكون كافرًا كفرًا أكبر بذلك، ولكنه كفر أصغر. والصواب: أنه كفر أكبر، هذا هو الأصح من قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة رواه مسلم في الصحيح؛ ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، ولأدلة أخرى تدل على كفر تارك الصلاة وإن لم يجحد وجوبها. فعليه أن يعيد العقد إذا كانت المرأة تصلي ومحافظة، أما إذا كانت مثله فلا إعادة، فالعقد صحيح؛ لأن الرسول ﷺ أقر الكفار على عقودهم لما أسلموا، لكن إذا كانت هي محافظة، وهو ليس محافظ يعاد العقد أو بالعكس إن كان محافظًا، هو وهي لا تحافظ يعاد العقد، يجدد العقد بعد التوبة، ممن كان غير محافظ عليه أن يجدد العقد ولو فيما بينهم من دون حاجة إلى القاضي أو إلى المأذون، إذا جددوا في البيت بينهم بحضرة شاهدين، وقال الولي زوجتك، وقال له: قبلت، على مهر ولو قليلًا، بحضرة شاهدين عدلين كفى، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14488/يجدد-عقد-الزواج-للمتساهل-في-اداء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_745/nour_74515.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":16148,"question":"يقول: تزوجت منذ فترة طويلة، ورزقت بأولاد وبنات، واكتشفت الآن أن زوجتي حين كتابة العقد لم تكن تصلي، كيف أتصرف الآن؟ جزاكم الله خيرًا.","title":"حكم تجديد النكاح إذا كان أحد الزوجين لا يصلي","answer":"الجواب: إذا كنت أنت تصلي، وهي لا تصلي؛ فالواجب في أصح قولي العلماء تجديد النكاح، يجدد النكاح بولي، وشاهدين، ومهر جديد، إذا كنت تصلي، وهي لا تصلي، أو العكس أنت لا تصلي، وهي تصلي؛ فإن الواجب تجديد العقد؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء.  فالواجب أن يجدد النكاح، تطلب من وليها أن يعقد لك عقدًا جديدًا بعدما تابت ورجعت إلى الله، فتجدد النكاح بمهر جديد، ولو قليل، ولو بمهر قليل، بحضرة شاهدين، ولو في البيت من غير حاجة إلى محكمة، ولا حاجة إلى مأذون في البيت في بيتكم، أو في بيت صهرك، أو في بيت أحد إخوانك، يجدد النكاح بحضرة شاهدين إذا رغبت فيك، ورغبت فيها بمهر جديد، ولو قليلًا، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14808/حكم-تجديد-النكاح-اذا-كان-احد-الزوجين-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75003.mp3","categories":["نكاح الكفار"]},{"id":16234,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع الحميدي، مقيم في الرياض السليمانية، أخونا له رسالة طويلة، وموضوع أطول يتعلق بالطلاق، يقول: تزوجت قبل خمسة أعوام، وكنت وقتها لا أصلي، ولا أصوم، ولا أقوم بأي فريضة أبدًا، كنت على خلاف دائم مع زوجتي، قلت لها ذات يوم: أنت طالق، أمام أهلها، وحضرت لهما في اليوم التالي، وأخذتها إلى بيتي بالمرة، ثم المرة الثانية أرسلت لها ورقة، وقلت لهما: أنت طالق، وبعد مرور ثلاثة أيام حضرت، وأخذتها إلى بيتي، وبعد مرور تسعة أشهر قررت السفر للسعودية، وأخبرت أهلها على طلاقها، ثم أخذوا عفشي من بيتي في غيابي مقابل أن أطلقها، المهم طلقتها تفاديًا للمشاكل، وحضرت للسعودية، والحمد لله استقمت، وعرفت الكثير عن الإسلام، وبدأت الصلاة والصوم، وحجيت أكثر من مرة، وحفظت الكثير من كتاب الله، مكثت في السعودية سنتين، ورجعت إلى بلدي، وعقدت عقدًا جديدًا، وبمهر جديد على زوجتي الأولى؛ لأنني سمعت من هذا البرنامج بأن الذي لا يصلي عقده باطل، لذا قلت: بأن زواجي من أوله باطل، ولذلك عقدت عليها من جديد، أرجو إفادتي عن صحة ما فعلت؟ جزاكم الله خيرًا.","title":"حكم من عقد على طليقته بعد أن كان تاركًا للصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.  إذا كان الواقع هو ما ذكرت في السؤال، وأنك حين تزوجتها وأنت لا تصلي، وهي تصلي فإن العقد يكون غير صحيح؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، وإن لم يجحد الوجوب، أما من جحد وجوبها؛ فإنه يكفر بإجماع المسلمين، وبذلك تبين بالطلقة الأولى، ولا يلحقها ما بعدها، ويكون عقدك الجديد بعد التوبة إذا كانت هي تصلي؛ يكون عقدك الجديد بعد التوبة صحيحًا، والحمد لله. ونسأل الله أن يهديكما جميعًا، وأن يصلح حالكما جميعًا، ويكون قد مضى عليها طلقة، وهي الطلقة الأولى، والطلقة الثانية، وما بعدها لا تلحقها لكونها تصلي، وأنت لا تصلي، فالعقد غير صحيح، ولا يلحقها بسبب ذلك إلا طلقة، والعمدة على النكاح الجديد الذي بعد التوبة، نسأل الله لنا ولكم الثبات على الحق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14926/حكم-من-عقد-على-طليقته-بعد-ان-كان-تاركا-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_807/nour_80701.mp3","categories":["نكاح الكفار","شروط وأركان الزواج"]},{"id":16250,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحرف (س) من الرياض، أخونا عنون رسالته بقوله: الموضوع: تكاليف في أوقات الصلاة، يقول: مع الأذان للصلاة يكلفونني بالمشاوير، ومليت كثيرًا من هذه التكاليف في وقت الأذان، وكثيرًا من المرات خرجت عن صوابي، وضاق خلقي؛ لأنهم لا يخرجون إلا مع الأذان، أو وقت الصلاة، كنت دائمًا أشكو لهم هذا، وأبين لهم أن الصلاة لها فضل كبير إذا كانت مع الجماعة، ولا يجوز تأجيلها لغرض من الأغراض التي يمكن تأخيرها، لم يستجيبوا لي، وجهوني ووجهوا أمثال هؤلاء، جزاكم الله خيرًا، وأحسن إليكم، والواقع أمامي رسالة أخرى -سماحة الشيخ- تعرض نفس الغرض، فتوجيهكم، وفقكم الله، وجزاكم خيرًا.","title":"حكم مَن يُلزم بالعمل في أوقات الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا شك أن الواجب على المسلمين العناية بالصلاة، وأن تؤدى في وقتها من الرجال والنساء جميعًا؛ لأنها عمود الإسلام، وأعظم الأركان بعد الشهادتين، ولأنها أول شيء يحاسب عليه العبد يوم القيامة، فإن صلحت له الصلاة؛ صلح له بقية عمله، وإن ردت عليه صلاته؛ رد عليه بقية عمله، ولا حول ولا قوة إلا بالله. فالواجب على أهل البيت، وعلى الموظفين في أي دائرة أن يتقوا الله في ذلك، وأن يتعاونوا على أداء الصلاة في وقتها في الجماعة، وأن يجيبوا المؤذن، وألا يشغل بعضهم بعضًا بأشياء تعوقهم عن الصلاة في الجماعة، أو عن الصلاة في وقتها، هذا يعم الرجال والنساء. الواجب على أهل البيت أن يجتهدوا في أداء الصلاة في وقتها، والحرص على ذلك، وعلى الرجال أن يصلوها في الجماعة، إذا سمعوا النداء؛ بادروا؛ لقوله ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس : ما هو العذر؟ قال: خوف، أو مرض». وثبت عنه ﷺ: «أنه جاءه رجل أعمى، فقال: يا رسول الله! ليس لي قائد يقودني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال له النبي ﷺ: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب. خرجه مسلم في الصحيح. فإذا كان أعمى، ليس له قائد، يقال له: أجب .. يصلي في الجماعة في المسجد، فكيف بغيره من الناس؟! فالواجب على جميع الرجال المستطيعين أن يصلوا في المسجد، وأن يجيبوا المؤذن، وأن يخرجوا من بيوتهم، ومنازلهم، ودوائرهم إلى المساجد، إلا من عذره الله، كالمريض، فالمريض يصلي على حسب حاله: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. يقول ابن مسعود  -الصحابي الجليل-: \"لقد رأيتنا، وما يتخلف عنها\" يعني: الصلاة في الجماعة \"إلا منافق معلوم النفاق، أو مريض\" فلا يجوز لمدير الدائرة، أو رئيس الدائرة، أو صاحب البيت أن يشغل أولاده، أو الموظفين؛ بأعمال تمنعهم من صلاة الجماعة، تعوقهم عن الصلاة في الجماعة، بل يجب أن يكونوا متعاونين على المبادرة في أداء الصلاة في الجماعة، وعلى تأجيل الأشغال الأخرى التي قد تعوق إلى ما بعد الصلاة، أو تقديمها قبل الصلاة بوقت. أما أن يشغل الموظفون بها وقت الصلاة حتى يتخلفوا عن صلاة الجماعة؛ فهذا منكر عظيم، فالواجب تركه، والحذر منه، نسأل الله للجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم، ما على العامل، أو السائق، أو الخادم إذا جوبه بمثل هذه القضية سماحة الشيخ! هل له، أو تنصحونه بأن ينتقل إلى جهة أخرى تمكنه من تأدية صلاة الجماعة؟ الشيخ: الواجب على السائق، والعامل، وكل موظف: أن يقدم حق الله، يصلي في الجماعة، يوقف السيارة، ويصلي في الجماعة، والحمد لله، والعامل يوقف العمل، ويصلي مع المسلمين، أوقات الصلاة مستثناة، ما هي داخلة في العمل إلا إذا كان حارسًا يصلي في محل حراسته؛ ولا يهمل محله، أو مريضًا؛ فهو معذور، أو معه في السيارة ما يخشى عليه؛ فلا بأس أن يؤديه إلى جهته، ويحرص مستقبلًا على أن يحتاط لهذا الأمر في جميع الأوقات، نعم. المقدم: جزاكم الله خيرًا، ومن كان عمله في الإمكان أن يؤجل ذلك العمل إلى ما بعد الصلاة، كيف تنصحونه؟ الشيخ: يجب عليه أن يؤجل، وإذا كانت الجهة المسؤولة لا تمكنه؛ ينتقل إلى جهة أخرى، يستقيل، ويطلب جهة أخرى، والله يسهل أمره، يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] ويقول : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] والنبي ﷺ يقول: لا طاعة لمخلوق في معصية الخالق ويقول -عليه الصلاة والسلام-: إنما الطاعة في المعروف. فالرئاسة التي تمنعه من صلاة الجماعة، أو الإدارة، أو رئيس العمل، أو ما أشبه ذلك؛ لا يجوز له أن يطيعه في ذلك. المقدم: أو رئيس العائلة مثلًا!  الشيخ: أو رئيس العائلة: إنما الطاعة في المعروف ليس للمكلف أن يطيع أحدًا في معصية الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14928/حكم-من-يلزم-بالعمل-في-اوقات-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75201.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":16385,"question":"من مرسى مطروح مصر العربية رسالة وبعث بها أحد الإخوة المستمعين هو عبدالباسط العميري، الأخ عبدالباسط له قضية يقول فيها: عندنا رجل كبير في السن يبلغ من العمر تسعين عامًا، ولديه زوجة لا تصلي، مع العلم أنه أمرها بالصلاة؛ فأبت، فهجرها؛ فصلت حينًا أي: بعض الأيام، وقطعتها، فأعطاها مرتبًا يوميًا، أي: بعض النقود، ثم قطعتها، فقال لها: أنا بريء منك يوم الحساب، وأترك الأمر إلى الله، فقلت له: طلقها، قال: لا أستطيع، أنجبت منها أولادًا كثيرين، وأنا رجل كبير في السن، ولا أستطيع الزواج مرة أخرى، وليس عندي من يعد لي الطعام، ويقوم بواجبي وواجب بيتي، فهل لهذا الرجل أن يبقى مع هذه المرأة والحال ما ذكر، أم توجهونه إلى شيء آخر، علمًا بأنه من المحبين لهذا البرنامج؟ جزاكم الله خيرًا.","title":"حكم بقاء الرجل المُسنِّ مع امرأة لا تصلي","answer":"الجواب: الصحيح من أقوال العلماء في هذه المسألة: أن تارك الصلاة عمدًا يكون كافرًا كفرًا أكبر، فهذه المرأة تعتبر كافرة كفرًا أكبر، وبخروجها من العدة بعد كفرها تكون غير امرأة له، لكن لا مانع من أن تخدمه، وأن تخدم ذريته أولادها، وعليه أمرها بالحجاب، وغض البصر عنها، وأن لا يخلو بها، ولا حرج أن تبقى في خدمة أولادها، وينفق عليها من أجل خدمة أولادها وأولاده، مع الدعاء لها بالهداية، ومع النصيحة؛ لعل الله يهديها فترجع إلى الصواب، وهكذا أهلها ينصحونها، لعل الله يهديها بأسبابهم. وبكل حال هو يعتبرها خادمًا لا زوجة، ولا يخلو بها، ولا ينظر إليها، ويأمرها بالحجاب عنه؛ حتى يهديها الله، ويردها للصواب، فإذا هداها، ورجعت للصواب؛ فهي زوجته، نعم. المقدم: جزاكم الله خيرًا، إذًا لا بد أن يكون موقفه حازمًا والحال ما ذكر؟  الشيخ: هذا الواجب عليه، واختلف العلماء: هل ترجع إليه بنكاح جديد، أم لا ترجع بنكاح جديد؛ لأنه لم يطلقها، وتبقى معلقة متى هداها الله رجعت إليه. الصواب: أنها ما دامت بهذه الحال، ولم ترغب النكاح بغيره، وهو لم يطلقها متى رجعت، وهداها الله فهي زوجته، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15086/حكم-بقاء-الرجل-المسن-مع-امراة-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75411.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":17239,"question":"هل يجوز -يا شيخ- أن يتزوج المسلم من امرأة من أهل الكتاب حتى ولو لم تسلم؟","title":"ما حكم زواج المسلم بالكتابية؟","answer":"الجواب: إذا كانت محصنة، معروفة بالإحصان، ليست من الزواني، حرة، قال الله تعالى: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ [المائدة:5] والمحصنة عند أهل العلم: الحرة العفيفة، فهي حرة هذه الأمة، وعفيفة، غير معروفة بالزنا، جاز نكاحها للمسلم خاصة، المحصنة من أهل الكتاب خاصة. أما من المجوس، أو من الوثنيين؛ لا، بس من أهل الكتاب فقط، والمسلمة أولى منها، وأفضل. نعم. المقدم: أحسن الله إليكم، سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16069/ما-حكم-زواج-المسلم-بالكتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59116.mp3","categories":["نكاح الكفار"]},{"id":17414,"question":"رسالة وصلت إلينا من العراق باعثتها إحدى الأخوات المستمعات، تقول: المستمعة (ت. هـ. س) تقول: كنت لا أصلي، وكذلك كان زوجي لا يصلي، والآن -وبحمد الله- بدأنا في الصلاة وفي تأدية الزكاة، كيف تنصحوننا والحال ما ذكر بالنسبة لما مضى من أعمارنا؟ جزاكم الله خيرًا.","title":"ماذا يفعل الزوجان إذا كانا لا يصليان ثم تابا؟","answer":"الجواب: إذا كنتما حين النكاح كلاكما لا يصلي، فالنكاح صحيح، وهكذا نكاح جميع الكفرة يقرؤن عليه، النبي ﷺ لما أسلم الناس أقرهم على أنكحتهم، ولم يأمرهم بتجديدها، فإذا كنتما جميعًا لا تصليان حين النكاح؛ فالنكاح صحيح، والتوبة عليكما لازمة، ومن تاب؛ تاب الله عليه، نعم. المقدم: جزاكم الله خيرًا، إذًا لا قضاء عليهما فيما فات؟ الشيخ: نعم، التوبة تكفي، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16280/ماذا-يفعل-الزوجان-اذا-كانا-لا-يصليان-ثم-تابا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_835/nour_83511.mp3","categories":["نكاح الكفار"]},{"id":18022,"question":"أيضًا تسأل سؤال طويل وتقول فيه: إنها متزوجة، وعندها أطفال وزوجها يستعمل المنكرات، ولا يحافظ على الصلوات فهو يصلي يومًا ويتركها أسبوع، وأنا لا أستطيع أن أترك البيت بسبب أطفالي، وأنا متبرئة منه ومن فعله، وأنا والحمد لله مسلمة أحافظ على صلواتي وأطيع ربي والحمد لله، ولكن مشكلتي في زوجي.أريد من سماحة الشيخ أن تتفضل بحل مشكلتي؛ ذلكم أنه ساءت معاملته معي وأذنب في حقنا الشيء الكثير، ما حكم جلوسي معه ومع أطفالي؟ جزاكم الله خيرًا.","title":"واجب المرأة تجاه زوجها التارك للصلاة","answer":"الجواب: الواجب عليك الخروج بأطفالك إلى أهلك إذا أمكن ذلك؛ لأن ترك الصلاة كفر أكبر في أصح قولي العلماء، ولو كان لم يجحد وجوبها، أما إذا جحد وجوبها كفر بالإجماع، لكن إذا لم يجحد وجوبها فإنه يكفر بتركها في أصح قولي العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه عن جابر  . ولقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن الأربع بإسناد صحيح عن بريدة ، مع أحاديث أخرى في ذلك. فإن لم تستطيعي الخروج جلست مع أولادك ومنعتيه نفسك لا تمكنيه من نفسك، لا من جماع، ولا تقبيل ولا غير ذلك حتى يستقيم حتى يصلي، وارفعي بأمرك إذا امتنع ارفعي بأمرك إلى المحكمة حتى تفرق بينك وبينه، وإن هداه الله بأسبابك وتاب إلى الله وصلى فالحمد لله، وإلا فالواجب عليك الامتناع منه، وأن لا يقربك لا بقبلة، ولا بجماع ولا بأشباه ذلك، ولك الخروج إلى بيت أهلك إن تيسر ذلك، بل يلزمك الخروج حتى تبتعدي عن طاعة الشيطان في حقه. ونسأل الله له الهداية، نسأل الله أن يمن عليه بالهداية. نعم.","link":"https://binbaz.org.sa/fatwas/17051/واجب-المراة-تجاه-زوجها-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_850/nour_85004.mp3","categories":["نكاح الكفار","حكم الصلاة وأهميتها"]},{"id":18097,"question":"ننتقل بعد هذا إلى رسالة وصلت إلى البرنامج من نينوى باعثة الرسالة إحدى الأخوات من هناك تقول السائلة (ل. ع. ج) أختنا تقول: أول سؤالي هو: أنا فتاة تزوجت من رجل لا يصوم ولا يصلي ويشرب الخمر، وكنت أنا أيضًا لا أصلي ولا أصوم، وبعد فترة من زواجي هداني الله  إلى الصلاة والصوم والحمد لله.أما بعد: فإني أريد أن أشرح لك حالتي مع زوجي هو أنني ساكنة في بيت أهله الذي يتكون من أربعة غرف، فكل واحد من إخوانه هو وزوجته ساكن في غرفة وليس لهم أطفال، أما أنا فغرفتي مكان للجلوس والأكل وللزوار، ومع العلم أن لي أربعة أطفال، ومع هذا كله فإن زوجي يعاملني معاملة قاسية ولا يصرف علي، ولا يعطيني أي شيء، ويشتمني ويشتم أهلي، وإذا مرضت أنا أو أطفالي فلا يقبل أن يعطيني أي مصروف، بل هو الذي يطلب مني مصروفًا، مع العلم أنه لا يوجد لي أي مورد.وكذلك فإنه يحرمني من رؤية أهلي وإخواني، أما من ناحيتي أنا فإنني أقوم بواجبه وواجب والدته على كل حال، وكذلك أقوم بواجب إخوانه المتزوجين وعلي مسؤولية البيت كله، وكذلك والدته تعاملني وتعامل أطفالي بقسوة وتقتلهم -لعلها تقصد الضرب- ولا أستطيع أن أعمل شيئًا، أرشدوني ماذا أفعل؟ جزاكم الله خيرًا، وماذا تنصحون هذه الأسرة في هذه المعاملة تجاهي؟","title":"ماذا تفعل مَنْ زوجها لا يصلي ولا يقوم بحقهم؟","answer":"الجواب: الحمد لله الذي هداك للصلاة والصيام وأعاذك من الشيطان، هذه أعظم نعمة وأكبر نعمة والحمد لله على ذلك. أما ما ذكرت من سوء المعاملة من الزوج ومن أم الزوج فعليك يا أيها الأخت في الله الصبر والاحتساب وفعل الخير، وصاحب الخير لا يندم بل عاقبته حميدة، لكن إن كان الزوج لا يصلي كما ذكرت سابقًا فلا خير فيه، ولا ينبغي البقاء معه بل ينبغي أن تذهبي لأهلك مع أطفالك ولا ينبغي البقاء معه مادام بهذه الحالة السيئة، لا يصلي ويشرب الخمر ويسيء العشرة؛ فهذا لا وجه للبقاء معه وسوف يعطيك الله خيرًا منه. فينبغي لك أن تبتعدي عنه وأن تذهبي إلى أهلك، وهو إن هداه الله بعد ذلك نظر في الأمر، وإلا فسوف يعطيك الله خيرًا منه وأفضل: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:1-3]، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. أما إن هداه الله ورجع إلى الصواب وتاب إلى الله وأدى الصلاة وترك المسكرات وأحسن العشرة فالحمد لله، نسأل الله له الهداية، أما إذا بقي على حاله فنصيحتي لك البعد عنه لئلا يضرك ويضر أولادك، ولئلا يجرك إلى شره، ولئلا يجر أولاده إلى شره أيضًا من ترك الصلاة وشرب المسكرات وسوء الأخلاق، نسأل الله السلامة والعافية. الحاصل من هذا والخلاصة: أني أنصحك أن تذهبي إلى أهلك بأولادك وأن تدعيه مادام على هذه الحالة السيئة من ترك الصلاة وتعاطي المسكرات، ونسأل الله لنا وله الهداية، ونسأل الله لك تيسير الأمور وتفريج الكروب وحسن العاقبة، وأن يثيبك على ما فعلت من الخير، وأن يرده للصواب وأن يهديه للصواب، وأن يهدي أمه أيضًا للصواب وحسن المعاملة إنه جل وعلا جواد كريم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17132/ماذا-تفعل-من-زوجها-لا-يصلي-ولا-يقوم-بحقهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90304.mp3","categories":["حكم الصلاة وأهميتها","نكاح الكفار"]},{"id":18589,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من جمهورية السودان، أخونا بدأ رسالته بمقدمة يقول فيها: الإخوة مقدمو برنامج (نور على الدرب) أحييكم تحية الإسلام الخالدة، مع الاحترام والتقدير والشكر -بعد الله تعالى- على دأبكم ومواظبتكم ونجاحكم بعون الله تعالى في تقديم هذا البرنامج الإسلامي العظيم؛ لتبصير المسلمين، وإرشادهم حول استفساراتهم الدينية والاجتماعية. ونسأل الله  أن يبقي هذا البرنامج ما بقي الدهر منارًا ومنبرًا، تتلقى منه الأجيال المسلمة عبر التاريخ تعاليم ديننا الإسلامي السمح، وأن يظل السادة أصحاب الفضيلة العلماء -أثابهم الله خير الثواب- حملة لمشاعل النور؛ ولحلول مشكلاتنا الدينية والاجتماعية، وإنني أشيد بهذا البرنامج الحي، وأتقدم بأسئلتي لكم لطرحها وعرضها على أصحاب الفضيلة العلماء؛ للتكرم بالإجابة عليها، سائلًا الله تعالى أن يثيبكم خيرًا، ويوفقكم، ويسدد خطاكم.بدأ أسئلته -سماحة الشيخ- بالسؤال التالي يقول: هل هناك شروط للزواج من المرأة الكتابية غير الدين الذي تدين به؟ وماذا على الشخص الذي ينجب أبناءً وبنات، ولم يوفق في إدخالهم الدين الإسلامي، وبالذات البنات، كيف يتم زواجهن؟ هل يسمح لهن بالزواج من غير المسلمين إن رغبن في ذلك؟","title":"حكم زواج المسلم من كتابية","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد أوضح الله سبحانه الشروط المعتبرة في نكاح أهل الكتاب، فقال : الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ [المائدة:5]. فالله  أباح لنا المحصنات من أهل الكتاب، إذا دفعنا لهن أجورهن وهي المهور، والمحصنة: هي الحرة العفيفة، فإذا تيسر للمسلم حرة عفيفة من أهل الكتاب، واتفق معها على المهر المطلوب وهو الأجر؛ جاز له نكاحها، بواسطة وليها، وليس هناك شروط أخرى فيما نعلم، إلا أنه ينبغي للمؤمن أن يلتمس المسلمات المحصنات، وأن يقدم ذلك على نكاح المحصنات من أهل الكتاب؛ لأسباب كثيرة، منها: أن ذلك أسلم لدينه، ومن ذلك أنه أسلم لذريته، ومن ذلك أن أخواته المسلمات أولى بالإعفاف، وأولى بالإحسان من الكافرات؛ ولهذا كان كثير من السلف يكره نكاح المحصنات من أهل الكتاب، ومنهم عمر  أمير المؤمنين. فنصيحتي لك -أيها السائل- أن لا تزوج من أهل الكتاب، وأن تلتمس محصنة مسلمة من أهل دينك؛ لأن ذلك خير لك في دينك ودنياك، وخير لك في العاقبة، وخير لذريتك -إن شاء الله-، لكن لو تزوجت محصنة من أهل الكتاب، فأولادها تبع لك، مسلمون ذكورًا كانوا أو إناثًا؛ لأن الولد يتبع خير أبويه، والمسلم خير من الكافر، فإذا كان الزوج مسلمًا والمرأة كتابية، فإن أولاده منها يتبعونه بحكم إسلامه، من غير حاجة إلى تجديد الإسلام، وعليك أن تسعى مجتهدًا في توجيه الأولاد إلى الخير، وإدخالهم المدارس الإسلامية حيث أمكن ذلك، أو تعليمهم في البيت. المقصود: أنك تجتهد في بعدهم من شر الكفرة، ومكائد الكفرة وشبه الكفرة، ومدارسهم إلا عند الضرورة، فإنهم يدرسون في المدارس الكافرة الدروس التي تنفعهم، ويكون لك عناية بهم من جهة الدروس الدينية، ولو بواسطة معلم خاص في البيت، إذا لم يتيسر لهم دروس في المدرسة الكافرة في بلد لا تدرس به دروس إسلامية، وكثير من المدارس يوجد فيها دراسات إسلامية، وإن كانت في دول كافرة. والخلاصة: أنك تجتهد في التزوج من المسلمات، وإذا قدر أنك تزوجت محصنة من أهل الكتاب، فإن أولادك منها تابعون لك، ومحكوم بإسلامهم، وعليك الاجتهاد في تربيتهم التربية الصالحة، توجيههم إلى الخير، والحذر من كل ما يسبب جرهم إلى الكفر بالله، واعتناقهم دين أمهم، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيراً، في حالة ما إذا اكتشف أن الأبناء لا زالوا على دين أمهم، وأنهم لم يعتنقوا الإسلام رغم محاولته، هل يسمح للبنات بأن يتزوجوا من أهل ديانة غير ديانة الإسلام؟ الشيخ: عليه أن يجاهد في أن تكون البنت مسلمة تبعًا له، وهكذا الولد الذكر، فيحرص على ذلك، وليس لها أن تتبع دين أمها، وليس للذكر كذلك أن يتبع دين أمه، فالواجب عليه أن يتبع دين أبيه، وهذا فرض عليه، وإذا استمر في متابعته لدين أمه -النصرانية- فهذا محل نظر؛ لأنه ينبغي له أن لا يتساهل معهم في ذلك، بل يجب أن يلاحظ دعوتهم للإسلام، وترغيبهم في الإسلام، وبذل المستطاع في الإسلام، حتى يتزوج بالمسلم، ويتزوج الولد بالمسلمة، ويبتعد الجميع عن خطر الكفر وشر الكفر، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17714/حكم-زواج-المسلم-من-كتابية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87101.mp3","categories":["نكاح الكفار"]}]
